export default [{"id":125,"question":"يسأل عن تأجير المنازل أو الشُّقق للعائلات الكافرة أو لشركات يعمل فيها الكفَّار؟","title":"ما حكم تأجير البيوت للكفار؟","answer":"الجواب: ينبغي الحذر من ذلك؛ لأنَّ هذه الجزيرة ليست للكفار، فلا يجوز إبقاؤهم فيها، ولا التساهل في ذلك، يقول النبيُّ ﷺ في الحديث الصحيح: لا يجتمع في هذه الجزيرة دينان، وأوصى عند موته بإخراج اليهود والنَّصارى من هذه الجزيرة، فالجزيرة مهد الإسلام، ومحلّ نشره، وموطن ظهوره، فلا ينبغي أن يقرّ فيها الكفار إلَّا بصفةٍ عارضةٍ لحاجةٍ عارضةٍ: كبريد رسول، وكطبيبٍ عند الحاجة إذا دُعي بواسطة ولي الأمر، وإلا فتساهل الناس مع هؤلاء العمال من الكفرة وغيرهم فيه خطرٌ عظيمٌ، وشرٌّ كبيرٌ، بإسكانهم المنازل، والتأجير لهم، وتسهيل أمورهم؛ مما يُرغِّبهم في المجيء والسكن، فيجب الحذر من هذه الأمور، وأن تكون بعيدًا عمَّا يُرغِّب أعداء الله في هذه الجزيرة.","link":"https://binbaz.org.sa/fatwas/3626/ما-حكم-تاجير-البيوت-للكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0111.mp3","categories":["الإجارة"]},{"id":126,"question":"ما حكم تأجير المحلات التّجارية على مَن يفتح محلًّا للحلاقة أو الخياطة النّسائية أو بيع أشرطة الفيديو أو أشرطة الغناء؟","title":"حكم تأجير المحلات لأمور منكرة أو مشبوهة","answer":"الجواب: لا تُؤجر المحلات لمَن يستأجرها لمعاصي الله، إنما تُؤجَّر لمَن يستأجرها للمُباح، فمَن استأجرها ليحلق لحى الناس أو ليبيع آلات الملاهي أو ليبيع الخمر أو أي شيء من المعاصي فلا تُؤَجَّر له، لا يجوز في أي مكانٍ كان، ولو في أمريكا، ولو في أي مكانٍ، وهو مسلم، فلا يجوز له أن يُعين على معاصي الله، لا باستئجاره، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/3632/حكم-تاجير-المحلات-لامور-منكرة-او-مشبوهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0114.mp3","categories":["الإجارة"]},{"id":372,"question":"هل يجوز للمسلم أن يُؤجِّر بيته للكافر، سواء كان كتابيًّا أو غير كتابي؟ وكيف يستطيع أن يُعامله إذا كان.....؟","title":"حكم وكيفية المعاملات مع غير المسلمين","answer":"الجواب: أما في هذه الجزيرة فلا؛ لأنَّ الله جلَّ وعلا حرَّم علينا إباحة هذه الجزيرة لهم، وأوصى النبي ﷺ بإخراج المشركين من هذه الجزيرة، كما ثبت في \"الصحيح\" أن النبي أوصى بإخراجهم من الجزيرة وقال: لا ألفين اليهود والنَّصارى في جزيرة العرب حتى لا أدع إلا مسلمًا، فهذه الجزيرة يجب أن تكون خالصةً للمؤمنين، ليس فيها أخلاطٌ، فهي مهد الإسلام، ومنبع الإسلام، وبلاد الإسلام التي خرج منها وانتشر منها، وقد قرر النبيُّ ﷺ أن يكون فيها دينٌ واحدٌ وهو الإسلام، وألا يكون فيها دينان.\nفلا يجوز للمسلم أن يتساهل في وجود المشركين فيها بالتأجير عليه، أو جلبه إلى العمل هنا، أو نحو ذلك، فلا يُستجلب للعمل: لا سائقًا، ولا عاملًا، ولا غير ذلك، ولا يُؤجّر عليه ما يُؤهله ويُرغبه في البقاء: من مزرعةٍ أو بيتٍ أو دكانٍ أو غير ذلك، اللهم إلا أن تضطر الدولةُ إلى شيءٍ من ذلك: كطبيبٍ مهمٍّ، أو ما أشبه ذلك للضَّرورة، كما أقرَّ النبيُّ ﷺ اليهود في خيبر للعمل؛ لما كان المسلمون مشغولين بالجهاد.\nفالحاصل أنَّ الواجب إبعادهم عن هذه الجزيرة، وألا يتساهل معهم فيها، أما في غير الجزيرة كالشام والعراق ومصر وغير ذلك فلا بأس أن يُؤجّرهم؛ لأنه يجوز لهم السكن، إلا إذا كان يُؤجّر على قومٍ يفعلون الباطل ويُعينهم على الباطل: كتأجير دارٍ على مَن يبيع الخمر، أو مَن يُحارب المسلمين، أو ما أشبه، لا، فلا يُؤجر عليهم ولو كان في بلاد الكفر، أما في بلاد الجزيرة العربية فلا، لا يُؤجر مطلقًا، لا يجوز التأجير عليهم مطلقًا؛ لأنَّ بقاءهم هنا ممنوع.","link":"https://binbaz.org.sa/fatwas/4629/حكم-وكيفية-المعاملات-مع-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0427.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":419,"question":"هل يجوز تأجير المحلات على أصحاب المعاصي: كحالق اللحية، وتارك الصلاة، أم أنَّ هناك تفصيلًا؟","title":"حكم تأجير المحلات لأصحاب المعاصي","answer":"الجواب: أما تأجيرها على الكفرة فلا، تأجيرها على النصارى أو على مَن يُعرف بالشرك -كالبوذية وأشباههم- فلا. أما العاصي فيجوز التأجير عليه، لكن إذا التمس الطيبين أحسن. أما تأجيرها على مَن يُقيم فيها المعاصي: مَن يجعلها موضعًا لحلاقة اللِّحَى، أو موضعًا لعمل الربا، أو موضعًا لبيع الخمور والمخدرات، هذا لا يجوز؛ لأنه إعانةٌ لهم على الإثم والعدوان.","link":"https://binbaz.org.sa/fatwas/4843/حكم-تاجير-المحلات-لاصحاب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0477.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":447,"question":"إذا اتفق صاحب التاكسي مع الفندق أو أحد المطاعم بأنه إذا أتى بزبائن يعطيه مقابل الزبائن هؤلاء، فيه شيء؟","title":"ما حكم أخذ أجرة مقابل جلب زبائن؟","answer":"الجواب: ما في شيء، بس عليه أن يتقي الله، لا يحابي، وعلى صاحب التاكسي لا يحابي، لا يجيبهم للفندق الغالي ويخلي الفندق اللي مناسبهم ويغرّهم ويخدعهم حتى يأخذ الفلوس، عليه أن يتقي الله.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6170/ما-حكم-اخذ-اجرة-مقابل-جلب-زباىن","audio":"https://files.zadapps.info/binbaz.org.sa/SEK005.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":462,"question":"صاحب العقار يشترط عقد سنة لإيجار سنة، فبعد مضي ستة أشهر لو أخلى المستأجر المنزل هل يرجع إليه النصف الباقي؟","title":"هل العقد بين المؤجر والمستأجر ملزم لهما؟","answer":"الجواب: لا ما يرجع؛ لأن العقد لازم إما يكملون وإلا يؤجره على غيره.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6187/هل-العقد-بين-الموجر-والمستاجر-ملزم-لهما","audio":"https://files.zadapps.info/binbaz.org.sa/3akar022.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":464,"question":"بعض الأشخاص يكون يستقدم عمالاً ويقول: آخر الشهر تسلمني -مثلاً- ألف ريال، ويُطْلِقهم لكي يعملوا؟","title":"ما حكم استقدام عمال وإطلاقهم مقابل أموال؟","answer":"الجواب: ما يصح هذا، لا يجوز، هذا أخذ مال بغير حق، ولا يجوز استقدامه إلا لمصلحته مثل ما صدر من الدولة، صدر من هيئة كبار العلماء، يكون الاستقدام على قدر ما سمحت الدولة؛ لأن هذا من باب المصالح العامة.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6189/ما-حكم-استقدام-عمال-واطلاقهم-مقابل-اموال","audio":"https://files.zadapps.info/binbaz.org.sa/estkdam024.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":524,"question":"الأموال التي يأخذنها من يضربن بالدف حلال أو حرام؟","title":"حكم الأجرة مقابل ضرب الدف بالأعراس","answer":"الجواب: لا حرج إن شاء الله؛ لأن الدف جائز في النكاح.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6355/حكم-الاجرة-مقابل-ضرب-الدف-بالاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/maram090 - 04 - .mp3","categories":["الكسب المحرم","الإجارة"]},{"id":750,"question":"إنني رجلٌ فطين والحمد لله، وأطلع غالبًا على مُروجي المُخدرات، إلا أني بعد أن علم بعض زملائي بأنني أكتشف هذه الطريقة السيئة أساؤوا إليَّ بنظرتهم: أنني جاسوس، أو أنني موسوس، أو غير ذلك، وتُدفع لي المُكافآت من الإجازة والنقود، فهل عملي هذا يُخالف الحياء أو الشَّرع؟","title":"ما حكم العمل في مكافحة المخدرات؟","answer":"الجواب: هذا من باب التعاون على البر والتقوى، من باب التعاون على الخير، الإنسان كونه يعتني بأهل المخدرات والمسكرات والذين يضرون الناس، فيرفع عنهم ما يتعاطونه ويُشيعونه بين الناس؛ هذا من باب التعاون على البر والتقوى، ومحاربة أهل الشرور، فليس عليه حرجٌ في ذلك إذا أخبر عمَّن يبيع المخدرات أو يستوردها ويُروجها؛ لأن هذا يضرُّ الناس ضررًا عظيمًا، فالذي يُساعد على إبعاده وعلى القضاء عليه وعلى منعه من هذا البلاء مأجورٌ، ولو كره بعضُ الناس، ولو أساء إليه بعضُ الناس؛ لأنه ساعٍ في إصلاح الأمة وسلمها من هذا الداء العظيم، والشر الوبيل.","link":"https://binbaz.org.sa/fatwas/20644/ما-حكم-العمل-في-مكافحة-المخدرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0567حكم العمل في محافحة المخدرات ابن باز فتاوى المحاضرات.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":772,"question":"ما رأيكم في رجلٍ أتى على بئرٍ أوقف في سبيل الله، فجعل عليها ماطورًا يخرج به الماء، ويقوم بتوصيل الماء إلى مَن يريده في مكانه، ولكنه لا يُعطي أحدًا الماء حتى يتقاضى منه بعضَ الأجر على قدر ما يُريد من الماء؟","title":"حكم مَن يُوصل ماء بئر موقوفة مقابل أجر","answer":"الجواب: إذا كان ولاةُ الأمر قد أقرُّوه على هذا، أو كان في البلد وافقوا على أمثاله، ولو كان ما فيها ولاة أمرٍ، وافق مع أهل بلدٍ والقرية على هذا؛ لأنها متعطلة، فجاء الله به وأصلحها، ووكلوا عليه الماطور، ونفعهم؛ لا بأس بذلك. أما إن كان ظالمًا في ذلك: بأن يوجد مَن يريد إيصال الماء بغير ثمنٍ وبغير تعبٍ وهو منعه من ذلك، وفرض أمره هو حتى يأخذ من أموال الناس؛ هذا يُمنع. أما إذا كان عن تراضٍ بينه وبين أهل البلد، أو عن إحسانٍ منه؛ لأنها معطلة، فأحسن في ذلك، وأخذ الشيء اليسير والأجر اليسير على قدر تعبه، أو أنَّ ولاة الأمور عيَّنوه في هذا، ووافقوا عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/20694/حكم-من-يوصل-ماء-بىر-موقوفة-مقابل-اجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0591ما رأيكم في رجل أتى على بئر موقوفه فيخرج منه الماء ويقوم بتوصيل الماء ويأخذ أجر على ذلك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":912,"question":"كثر استقدام النَّصارى من العاملين بحجّة الخبرة أو الزراعة أو غير هذا، حتى أن البعض منهم عملوا بقرب حدود مكة، فما حكم هذا؟","title":"حكم استقدام النصارى بحجة الخبرة ونحوها","answer":"الجواب: استقدام الكفرة من المصائب العظيمة في هذه الجزيرة، والرسول ﷺ أوصى بإخراجهم من الجزيرة وقال: لا يجتمع فيها دينان، فهي مهبط الوحي، ومنبع الرسالة، فالواجب تطهيرها من الكفرة، إلا من عارضٍ: كالذي يقدم لبيع حاجات ميرة أو أشياء ثم يرجع، أو يقدم للاتِّصال بولي الأمر مُرْسَلًا من دولته، أو ما أشبه ذلك.\nأما استقدامهم للعمل فيها والإقامة فيها فهذا خطيرٌ، فظاهر الأدلة منعه، إلا من حاجةٍ يراها ولي الأمر خاصةً في مصلحة المسلمين: كطبيبٍ تدعو له الحاجة، أو عاملٍ تدعو له الحاجة لإصلاح سلاحٍ، أو غيره.\nولهذا استخدم النبيُّ ﷺ اليهود في خيبر للحاجة، ثم أجلاهم عمر، ولم يزل يقبل الرسل عليه الصلاة والسلام المرسلة من دولهم، فيأخذ معهم ويُعطي فيما قدموا إليه.\nأما استقدامهم على هذه الحال للخدمة: من سوّاقين، أو خدم، أو عمال، هذا لا يجوز، والواجب على ولاة الأمور -وفَّقهم الله- أن يحدّوا من هذا الأمر، وأن يجتهدوا في تخليصه وتقليله حسب الطاقة، وقد وعد خادمُ الحرمين بذلك -وفَّقه الله- ونسأل الله أن يُعين على التنفيذ.\nوالواجب على الأمة ألا تتساهل في هذا الأمر، وأن تكون عونًا لأهل الخير في هذا الأمر، كل إنسانٍ عنده شركة أو مصنع يجتهد في استقدام المسلمين، ولو كانوا أغلى، الله يبارك له ويُعينه، لكن المصيبة ضعف الإيمان، هذا يدَّعي أن المسلم غالٍ، وهذا يدَّعي أن المسلم يروح يُصلي ويُضيع بعض الوقت، وهذا من البلاء العظيم، نعوذ بالله.\nالواجب أنه يستقدم المسلمين، يكون نفعه في المسلم أو المسلمة، لا في الكفرة، وإذا كان في بلاد المسلمين مسلمون أو مسلمات استقدمهم، والمسلمون موجودون في مصر، في الشام، في العراق، في الهند، في باكستان، في أي مكانٍ، يتحرى وكيله، ويجتهد في استقدام الطيبين من المسلمين والطيبات عند الحاجة، حتى تكون الأموال في المسلمين لا في غيرهم، وحتى لا يُستقدم لهذه الجزيرة إلا المسلمون.\nهذا الواجب على مندوبي الشركات، وعلى الشركات أنفسها، وعلى المؤسسات، وعلى الدولة، وعلى كل أحدٍ، الواجب التواصي بهذا الأمر، والحرص والنصح لله ولعباده، وعدم إيثار الدنيا بالمقالات الفاسدة: أن هؤلاء أرخص، أو: هؤلاء أنصح، أو: هؤلاء كل وقته في العمل؛ كل هذا باطلٌ، المسلم أنصح وأطيب، فإذا أخلَّ المسلم فهو لضعف إيمانه، وضعف إسلامه، إذا كان إيمانه قويًّا سوف ينصح أكثر من الكافر، وسوف يقوم بالمهمة أكثر من الكافر، فلا يخلّ بالأمانة إلا من ضعف إسلامه، أو عدم إسلامه.","link":"https://binbaz.org.sa/fatwas/20947/حكم-استقدام-النصارى-بحجة-الخبرة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0743حكم استقدام النصارى بحجة الخبرة والزراعة أو غير ذلك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":1065,"question":"نرجو من سماحتكم بيان حكم مَن يأتي بالعمال من الخارج، ويُسرِّحهم في البلاد ليعملوا لحسابه، وفي مقابل ذلك يأخذ عليهم مبلغًا معلومًا، أو نسبةً من مكاسبهم، وهل هذا جائزٌ أم لا؟","title":"حكم الكفيل الذي يترك عماله مقابل مبلغ مالي","answer":"الجواب:\nهذه المسألة درسها مجلسُ هيئة كبار العلماء، وقرر فيها المنع، وأنه لا يجوز لأسبابٍ كثيرةٍ، منها: أنه يأخذ هذا في غير مقابل ما يأخذ، ومنها أنه سببٌ للفساد في الأرض، لا يهمه إلا هذا الذي يأخذ، وربما أتى بعمالٍ يضرُّون الناس من الكفرة والفسقة. فليس له أن يستقدم إلا على الطريق التي رسمتها الدولة، عليه أن يتحرى ما أقرَّته الدولة، وما رسمته الدولة، فيستقدم على ذلك الطريق؛ لأنَّ ذلك هو المباح من جهة الدولة، وعلى العبد السمع والطاعة، ولأنه الطريق إلى تخفيف الشرِّ، والسلامة من شرِّ المستَقْدَمين، وإلى أكل الحلال أيضًا.","link":"https://binbaz.org.sa/fatwas/21117/حكم-الكفيل-الذي-يترك-عماله-مقابل-مبلغ-مالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0913ما حكم من يأتي بالعمال من الخارج ويسرحها في البلاد يعملون لحسابه وفي المقابل يأخذ عليها مبالغ؟.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":1517,"question":"إنسانٌ عنده عمارة، ويؤجر بعض المحلات للذين يبيعون الدش وأجهزة التليفونات والتلفاز، فما حكم هذا؟","title":"حكم تأجير المحلات لمن يبيع \"الدِّشّ\" ونحوه","answer":"الجواب:\nيُؤجِّر على غيرهم أحوْط، وإلا فهذه مخلوطة لا بأس، أقول: مخلوطة فيها الخير والشر.\nس: فيها دشّ؟\nج: لا يجوز بيع الدش.\nس: هو أجَّرها عليهم؟\nج: لا يؤجر على الذين يبيعون الدُّشوش.","link":"https://binbaz.org.sa/fatwas/21616/حكم-تاجير-المحلات-لمن-يبيع-الدش-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأجير المحلات لمن يبيعون الدش وأجهزة التليفونات والتلفاز.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2158,"question":"بالنسبة لسعي السِّمسار: هل من حقِّ السمسار أم من حقِّ المالك؟","title":"هل أجرة السمسار حقِّ له أم للمالك؟","answer":"الجواب:\nهذا على مَن شُرِطَ عليه: إن كان شُرِطَ على البائع فعلى البائع، وإن كان شُرِطَ على المشتري فعلى المشتري، فالسمسار دلَّالٌ.\nس: هذا الأمر مفروغٌ منه، لكن محلّ السؤال هنا أن بعض السَّماسرة يبيعون للمالك السّلعة بثمنٍ جيدٍ ومكسبٍ ممتازٍ وفوق هذا فإنَّ هذا المالك الغني يشترط نصفَ السّعي له؟\nج: إذا ما أعطاه إلا النصف فالمسلمون على شروطهم، فإذا كان لهذا السعي جنيه ونصف على المئة، فقال: ما أُعطيه إلا ريالًا وربعًا، فلا بأس، فالمسلمون على شروطهم؛ لأنه قد تكون له أموال كثيرة فنصف السّعي ينفعه.\nس: لا، المشتري يدفع السعي كاملًا، ولكن المالك...؟\nج: المسلمون على شروطهم، فإذا شرطوا ذلك فلا بأس.","link":"https://binbaz.org.sa/fatwas/22279/هل-اجرة-السمسار-حق-له-ام-للمالك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سعي السمسار هل من حقِّ السمسار أم من حقِّ المالك.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2202,"question":"صاحب محلٍّ عنده عاملٌ يُشَغّله، ويقول له: راتبك عبارة عن نسبة من الربح، فإذا ربحت مثلًا 5% أو 10% يكون راتبك نسبةً من هذا الربح، فلو ربح مثلًا ألف ريـال تكون له من الألف مئةُ ريـال؟","title":"حكم إعطاء الأجير أجرته بنسبة من الربح","answer":"الجواب:\nإذا كان عنده عامل بجزء مشاع، فيضع عنده السلعة فيبيعها بنصف الربح أو بثلث الربح فلا بأس؛ لأنَّه معروفٌ، ما هو مجهولٌ.","link":"https://binbaz.org.sa/fatwas/22325/حكم-اعطاء-الاجير-اجرته-بنسبة-من-الربح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعطاء الأجير أجرته بالنسبة من الربح.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":2226,"question":"تأجير المحلات على العُمَّال؟","title":"حكم تأجير المحلات للعاملين فيها؟","answer":"الجواب:\nيبيع فيه ويشتري أو يسكنه؟\nس: لا، للبيع والشراء، للتجارة.\nج: لا بأس، والأجرة ما هي؟\nس: الاتفاق أن يكون بينهم راتبٌ، لكن هو يُسقط الراتب.\nج: المقصود أن يترك في الدّكان وكيلًا يبيع ويشتري عنه بالوكالة، لا بأس.\nس: العامل يُعطي الكفيلَ كل شهر ألفي ريـال، والبضاعة من العامل، والبيع والشراء كله من العامل؟\nج: هذه أجرة عن المحل، والعامل هو الذي يبيع ويشتري.\nس: والبضاعة من العامل؟!\nج: ما فيها شيء، هذه تُسمَّى: أجرة المحل.\nس: لكن العامل أتى من بلاده بناءً على عقدٍ بينه وبين الكفيل، على أن يُعطيه راتبًا؟!\nج: إذا تسامحوا لا بأس، فإذا تنازل العاملُ وصار في محلِّ تجارةٍ بأجرةٍ يُسلِّمها لكفيله، وهو الذي يعمل في المحلِّ أو يسكن في المحلِّ لا بأس.\nس: وإذا كان العاملُ يدفع الإيجارَ ويدفع أيضًا مئتي ريـالٍ للكفيل؟\nج: لا، ما يجوز أخذ شيءٍ على الكفالة، لكن يستأجر المحلَّ الذي فيه البيع والشّراء أو السكن، لا بأس.\nس: لكن النظام يمنع العاملَ أن يتَّجر بنفسه؟\nج: إذا كانت الدولةُ تمنع لا يعصي الدولة، ويُراجع الدوائر في هذا؛ لأنَّ هذه أمور تتعلق بمصلحة المسلمين، وعليه السمع والطاعة، ويمشي على التَّعاليم.","link":"https://binbaz.org.sa/fatwas/22349/حكم-تاجير-المحلات-للعاملين-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ الأجرة عن المحلات المؤجرة للعمال.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":3126,"question":"رجل اتفق مع جماعة، هو محام في أحد البلاد، اتفق معهم على أنه يخلّص لهم حقوقًا عند الدولة فلمّا سعى وبذل مجهودًا وأنفق من جيبه أموالًا في هذا الأمر فإذا الأمر تيسّر وأخذوا حقوقهم، وكان اشترط عليهم أن يعطوه نسبة عشرين في المئة من هذه الحقوق ووافقوا على ذلك، فقال نظرت في الأمر فوجدت أن ربما لو ما بذلت هذا المجهود كانت وصلتهم الحقوق. فهل يجوز له أخذ هذه النسبة؟","title":"حكم أخذ نسبة مقابل تخليص الحقوق المالية","answer":"الجواب: إذا استأجروه يخلِّص حقوقهم ما فيه شيء.\nس: استأجروه على نسبة.\nالشيخ: إذا أنه يخلص حقوقهم ما يخالف.\nس: يقول إن الحقوق تخلصت بطريقة سهلة، كان من الممكن تتخلّص بدونه، لكن بعد ما بذل مجهودًا وأنفق أموالًا؟\nالشيخ: ما في بأس.","link":"https://binbaz.org.sa/fatwas/23287/حكم-اخذ-نسبة-مقابل-تخليص-الحقوق-المالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ نسبة معينة مقابل تخليص الحقوق.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":3442,"question":"الذين يَفِدُون بالعمال الآن من الكفار: يُعتبر هذا؟ يُوَفّى لهم بعهدهم، أم أنه لا بدّ أن يخرجوا؟","title":"حكم استقدام السفراء والعمال من الكفار","answer":"الجواب: ظاهر النص المنع، إلا مَنْ قَدِم لحاجة مؤقتة، مثل من يَقْدُم بميرة يبيعها، أو الرسول البريد الذي يأتي من الكفار، أو ما أشبه ذلك. أما هؤلاء الذين يأتون ويقيمون فيفسدون في الأرض، ويضرون المجتمع الإسلامي؛ فلا يجوز استقدامهم للعمل هنا في الجزيرة إلا للضرورة التي تدعو لها مصلحة المسلمين من إعداد سلاح، أو طب خاص، أو ما أشبه ذلك من الأشياء الفردية التي يحتاجها المسلمون، أما إطلاق هذا الأمر أن الناس حتى يستقدموا من شاؤوا فهذا لا يجوز، وقد صدر قرار من مجلس هيئة كبار العلماء من سنوات بهذا الأمر، ورُفع إلى ولي الأمر لمنع هذا التساهل، نسأل الله أن يعين على ذلك.\nس: صاحب المؤسسة يأثم يا شيخ إذا جاء بهم؟\nالشيخ: نعم ما يجوز له استقدام الكفرة، الواجب استقدام المسلمين، المسلمون هم في حاجة للنفع؛ فيختار من المسلمين من يظهر صلاحه، لا يأخذ من هب ودب، بعض المسلمين يدّعي الإسلام، وهو وثني يعبد غير الله؛ فينبغي للوكيل الذي يستقدم أو يتعاقد مع الناس ينبغي له أن يكون نبيهًا؛ حتى لا يختار ولا يتعاقد إلا مع من عرف بالإسلام الصحيح، ولا يتساهل في استقدام الكفرة، أو المخلّطين المعروفين بالوثنية، وهم يدّعون الإسلام.\nس: والسفراء، سفراء الدول؟\nالشيخ: السفير مستثنى؛ لأنه تدعو الحاجة إلى ذلك، مثل ما استُثني في وجوده بين الكفار، النبي ﷺ بعث أبا عبيدة سفيرًا في نجران بين النصارى.\nس: يعتبر كبيرة من كبائر الذنوب استقدام الكفرة؟\nالشيخ: على كُلٍّ معصية، أما كونه كبيرة فمحل نظر، لكنه لا يجوز؛ لأنه ما فيه وعيد، فيه وصية بإخراجهم، والكبيرة لها شروط.","link":"https://binbaz.org.sa/fatwas/23617/حكم-استقدام-السفراء-والعمال-من-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يوفى بعهد العمال من الكفار، وحكم استقدامهم، وحكم السفراء.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":4397,"question":"استأجرت محلًّا في أحد الأسواق التجارية، وبقيت في هذا المحل سنة، وكان دخل هذا المحل جيدًا، ويأتينا أحد من الناس ويقول: أعطيك نقل قدم مثلًا مائتي ألف ريال وأحل محلك، وصاحب الأسواق التجارية راضٍ؟","title":"حكم إيجار المرء ما لا يملكه","answer":"الجواب: تؤجره محلك بس بقية المدة التي لك بس، وإلا ما لك حق في الزيادة، لك تؤجر بقية المدة بقليل أو أكثر إذا كان مثلك أو أقل ضررًا، إذا كان عمله مثلك أو أقل ضررًا.\nس: وإذا كان صاحب الملك راضيًا؟\nج: ولو راضٍ، تؤجر شيء ما تملكه؟ لا، تؤجره الباقي بس.","link":"https://binbaz.org.sa/fatwas/24674/حكم-ايجار-المرء-ما-لا-يملكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إيجار ما لا يملكه.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":4875,"question":"إذا كان الراقي يفرغ نفسه في وقت معين، ثم يشترط على الذي يقرأ عليه مبلغًا معين ويضع لوحة تدل عليه؟","title":"حكم اشتراط الراقي مبلغًا ووضعه لوحة تدل عليه","answer":"ما أعلم فيه شيء، لكن إذا تسامح يكون أحسن، وإلا الصحابة شرطوا.\nس: لكنه يشترط؟\nج: لا بأس أن يشترط لكن ينبغي له أن يتسامح لا يشدد على الناس؛ لأن الناس بحاجة إلى من يرقيهم.\nس: لكن هل من السنة أن يضع لوحة ويدل على نفسه؟\nج: الأمر واسع إن شاء الله؛ لأن الناس قد يحتاجون إلى هذا.","link":"https://binbaz.org.sa/fatwas/25361/حكم-اشتراط-الراقي-مبلغا-ووضعه-لوحة-تدل-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراط الراقي مبلغًا معين ووضعه لوحة تدل عليه.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":4876,"question":"ما وجه الخبث في كسب الحجام؟","title":"ما سبب وصف كسب الحجام بالخبيث؟","answer":"الله أعلم، لعلها من جهة إخراج الدم ومص الدم، فالدم أصله خبيث؛ لعله من أجل جهة إخراج الدم. وبعض أهل العلم قالوا: من باب التعاون بين المسلمين؛ فلا يأخذ أجرًا لأنها مسألة بسيطة فلا ينبغي أن يأخذ عليها أجرًا، مثل ما يعامل أخاه في الأشياء الخفيفة، ما تحتاج أجرًا، كونه يحمل له متاعه إلى السيارة أو على مطيته ما يحتاج يعطيه عليه أجرة، وهكذا الأمور البسيطة ما ينبغي فيها الأجر، من باب التعاون.","link":"https://binbaz.org.sa/fatwas/25363/ما-سبب-وصف-كسب-الحجام-بالخبيث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجه الخبث في كسب الحجام.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5041,"question":"بعضهم يأتي بكافرةٍ (خادمة)؟","title":"حكم استقدام الخادمة الكافرة؟","answer":"الجواب: لا، ما يجوز هذا، لا يجوز أن يأتي بكافرةٍ، يجب إبعادها، هذه الجزيرة العربية ما يكون فيها الكفار، النبي ﷺ أمر بإخراج الكفرة من هذه الجزيرة، لا من الرجال، ولا من النساء، والواجب عليه ردّها إلى بلادها.","link":"https://binbaz.org.sa/fatwas/29002/حكم-استقدام-الخادمة-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استقدام الخادمة الكافرة؟.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5164,"question":"سؤال عن استقدام بعض الناس لعُمَّال، ثم تركهم والأخذ عليهم في كلِّ شهر مبلغًا معينًا؟","title":"حكم استقدام العُمّال وأخذ مبالغ مالية عليهم","answer":"الجواب: أولًا: لا يجوز استقدام الكفرة، بل يجب الحذر من ذلك، أما المسلمون فلا بأس باستقدامهم على الطريقة التي رسمتها الدولة، فالدولة رسمت كيفية الاستقدام، فعلى المُستقدم أن يسير على ما بيَّنَتْه الدولةُ ورسمته، هذا هو الواجب على مَن يريد الاستقدام، حتى لا يضرَّ الناس باستقدام مَن لا ينبغي استقدامه.","link":"https://binbaz.org.sa/fatwas/30089/حكم-استقدام-العمال-واخذ-مبالغ-مالية-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 113.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5165,"question":"هذا يقول: السلام عليكم ورحمة الله وبركاته، ما حكم تأجير المحلات التّجارية على مَن يفتح محلًّا للحلاقة أو الخياطة النّسائية أو بيع أشرطة الفيديو أو أشرطة الغناء؟","title":"حكم تأجير المحلات التجارية لأمور محرَّمة","answer":"الجواب: لا تُؤجر المحلات لمَن يستأجرها لمعاصي الله، إنما تُؤجَّر لمَن يستأجرها للمُباح، فمَن استأجرها ليحلق لِحى الناس أو ليبيع آلات الملاهي أو ليبيع الخمر أو أي شيء من المعاصي فلا تُؤَجَّر له، لا يجوز في أي مكانٍ كان، ولو في أمريكا، ولو في أي مكانٍ، وهو مسلم، فلا يجوز له أن يُعين على معاصي الله، لا باستئجاره، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/30090/حكم-تاجير-المحلات-التجارية-لامور-محرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 114.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5181,"question":"رجلٌ يقول: أنا من الموظفين في مكة المكرمة، وعندما يأتي إليَّ الحجاج يُريدون أن أستأجر بيتًا، فأتفق أنا وصاحب البيت على أن يُؤجرهم مثلًا بألفين، ولي منه ثلاثمئة ريـال، فهل هذه رشوة؟","title":"حكم أخذ عمولة من مبالغ تأجير البيوت","answer":"الجواب: لا بدّ أن يُعلمهم إذا اتفق هو وإياه، فلا يجوز إلا أن يُعلمهم؛ لأن هذه من جنس الرشوة، لأنه يُخبرهم أنه بألفين وما هو بألفين، بل بألف وسبعمئة، فهذا ما يجوز، هذا من الرشوة، فإذا كان يريد الحلال فليقل لهم: إني اتفقتُ معه على أنها بألفين، وأن لي ثلاثمئة إذا كنتم تسمحون بذلك، وإلا فليس له إلا ألف وسبعمئة، وهو وافق على الثلاثمئة لي إن سمحتم بها، وإلا تركتها، أو ما أشبه ذلك من الكلام، يعني: لا بدّ أن يُبين لهم، وإلا فهو خيانة.","link":"https://binbaz.org.sa/fatwas/30117/حكم-اخذ-عمولة-من-مبالغ-تاجير-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 143.mp3","categories":["الكسب المحرم","الإجارة"]},{"id":5844,"question":"فضيلة شيخي، أنا أرغب في استقدام خادمة من الخارج بسبب أن أهلي مصابين بمرض منذ خمس سنوات، ويتعبهم عمل البيت، أرجو من سماحتكم إيضاح الحكم من استقدام الخدامة، وفق الله فضيلتكم؟","title":"حكم استقدام الكافر إلى الجزيرة العربية","answer":"الجواب: مهما أمكنك أن تجد ما يغنيك عنها فهو الذي ينبغي كما سمعت، ينبغي لك أن تساعد جاهدًا في إيجاد ما يغنيك عن ذلك، كأمها، أو خالتها تكون عندها، أو عمتها، أو بنتها، أو ما أشبه ذلك؛ لعلك تستغني بذلك، وإذا كان الشيء قليلًا تستطيع أن تقوم به أنت؛ فافعل ذلك، مهما أمكنك أن تستغني عن الخدامة؛ فهو خير لك، وأسلم لدينك، ودنياك. وإذا اضطررت إلى ذلك؛ فلتكن الخدامة بعيدة عن الفتنة، كبيرة السن، ليس فيها ما يدعو إلى الفتنة من الجمال مهما أمكن، ولا تخلو بها إذا كانت عندك، بل تكون مع أهلك، ولا تخلو بها، ولا يجوز لك الخلوة بها، هذا هو الواجب عليك عند الضرورة. ولا تستقدم كافرة، لا يجوز استقدام الكافرات أبدًا، هذه الجزيرة، أولًا هذه الجزيرة لا يجوز أن يقيم فيها الكافر، بل يجب أن تبقى بلاد إسلام، كما أمر النبي ﷺ في إخراج الكفار منها، وأوصى بذلك فهي محل للمسلمين، ولا يجوز أن يبقى فيها الكفار، اللهم إلا للضرورة بصفة مؤقتة لحاجة، كقادم لبيع سلع، لبيع ميرة، لبيع حاجات، ثم ينصرف إلى بلاده، أو مستقدم لحاجة تراها الدولة مهمة، فيستقدم لها لطب، أو هندسة يحتاج إليها بصفة مؤقتة، ثم يرجع إلى بلاده، فيستغني عنه كما استقدم النبي ﷺ اليهود في خيبر، فلما استغني عنهم؛ أبعدهم عمر، وأجلاهم عمر، رضي الله عنه وأرضاه. فالحاصل: أنه لا يجوز استقدام الكافرات؛ اللهم لعلة مؤقتة، وضرورة، ثم يبعدون، أما استقدامهم ليخدموا ففيه مضار كثيرة: أولًا: وجودهم في الجزيرة. ثانيًا: أن وجود الكافرات يربون الناس على الشر، والفساد، والكفر بالله  ويربون الصغار على الشر، والفساد، ويتأسى بهم أهل البيت على الشر، والفساد أيضًا.  فلا يجوز استقدامهم، ولا استخدامهم أبدًا، وهكذا العمال لا يجوز استقدامهم هنا للعمل، بل يستقدم المسلمون من سائر البلاد؛ ليستغنى بهم عن العمال الكافرين، وقد ناصح العلماء الدولة في ذلك، والدولة وعدت بأنها سوف تعمل ما تستطيع من تقليلهم، وإبعادهم واستبدالهم للمسلمين، فنسأل الله لهم العون.","link":"https://binbaz.org.sa/fatwas/1198/حكم-استقدام-الكافر-الى-الجزيرة-العربية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_194.mp3","categories":["الإجارة"]},{"id":5980,"question":"رجل يقرأ على المرضى بالقرآن، والأدعية النبوية، وقبل القراءة يحدد المال الذي سيأخذه من المريض، فما هو رأي سامحتكم في هذا؟","title":"حكم أخذ المال مقابل الرقى الشرعية على المرضى","answer":"الجواب: لا بأس بذلك إذا كان يقرأ ما تيسر من القرآن، ويدعو لهم بالدعوات، وينفث على المريض، لا بأس أن يحدد الأجر الذي له.  كما وقع لبعض الصحابة مع لديغ لدغ، وكانوا نزلوا بهم، ولم يضيفوهم، فجاءوا إليهم يطلبون من يرقي ليرقي هذا المريض، فقالوا: إلا أن تضربوا لنا سهمًا، فضربوا لهم شيئًا قطيعًا من الغنم، فرقوه حتى عافاه الله، وسلموا لهم نفس الأجرة، وبلغوا النبي ﷺ فأقرهم على ذلك.","link":"https://binbaz.org.sa/fatwas/1362/حكم-اخذ-المال-مقابل-الرقى-الشرعية-على-المرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_320.mp3","categories":["الإجارة","الطب والتداوي","الرقى والتمائم"]},{"id":6116,"question":"إذا كانت والدتي يصيبها التعب الشديد من جراء عمل البيت، ونريد أن نستقدم شغالة كافرة، مع العلم أن في البيت أربع أبناء غير متزوجين، وكذلك ما الحكم لو وجدت الشغالة في المنزل، وأنا لا أستطيع أن أخرج من البيت أيضًا؟ وما الحكم في الكلام معها كي تدخل الإسلام؟","title":"حكم استقدام خادمة كافرة","answer":"الجواب: سمعت الكلام أيها السائل، وأن هذا لا يجوز أبدًا، لا يستقدم شغالة كافرة أبدًا، وما دام البيت فيه أبناء فوجود شغالة بينهم -ولو مسلمة- فيه خطر عظيم؛ فلا ينبغي هذا، بل ينبغي أن يستعين بالله، وأن يعملوا ما يستطيعون حتى يتزوجوا، وتخدمهم أزواجهم.","link":"https://binbaz.org.sa/fatwas/1518/حكم-استقدام-خادمة-كافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_448.mp3","categories":["الإجارة"]},{"id":6122,"question":"ما الحكم إذا كان عندي خادم وثني يعبد بوذا، أو نصراني يقول: الله ثالث ثلاثة، وأنا لا أنكر عليه، ولا أدعوه إلى الإسلام، ويختلط بأبنائي، أفيدوني، وانصحوني، أثابكم الله؟","title":"ما الواجب على من لديه عمال كفار؟","answer":"الجواب: سمعت الكلام! يجب عليك أن تبعده، وأن تنهي عقده، وألا يبقى عندك لا النصراني، ولا البوذي، البوذي أكفر من النصراني، البوذي وثني أكفر، والهندوسي وثني أكفر، فيجب عليك إبعاد ذلك، وإنهاء عقودهم، واستبدالهم بالمسلمين، ولا خير في بقاء هؤلاء عندك، فهم شر عليك في الدين والدنيا، إلا إذا هداهم الله إلى الإسلام، وقبلوا منك، ودعوتهم إلى الإسلام، وهداهم الله، وقبلوا؛ فلا بأس. واحذرهم فقد يكون إسلامهم غير حقيقي، ولكن اقبل منهم الإسلام، وادعهم إلى الإسلام، فإذا قبلوا؛ فلك أجر عظيم، ولعلهم يكونوا صادقين مع المراقبة، والعناية، فإذا رأيت عليهم أمارات الصدق، وظهور دلائل قبول الإسلام، فهذه نعمة من الله عليك، وعليهم، والحمد لله، ومع هذا تراقبهم، وتلاحظهم؛ حتى لا تكون مخدوعًا بهم، وهم كاذبون.","link":"https://binbaz.org.sa/fatwas/1519/ما-الواجب-على-من-لديه-عمال-كفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_449.mp3","categories":["الإجارة"]},{"id":6216,"question":"بعض الأفراد حسب ما نسمع يستقدمون أشخاصًا من الخارج على أن يدفع ذلك الشخص المستقدم مبلغًا من النقود، مع العلم أنه إذا لم يدفع ذلك المبلغ لا يحصل له الوصول إلى هذه البلد لكي يكسب المعيشة له ولأولاده، فهل على الذي يستقدمه، ويأخذ منه مبلغًا، وهل يدخل في حديث: من باع حرًا وأكل ثمنه نرجو الإفادة؟","title":"حكم من استقدم عمالاً من الخارج وأخذ مالاً على ذلك","answer":"الجواب: ليس هذا من بيع الأحرار، ولكن هذه معاملة، ظاهر كلام أهل العلم منعها؛ لأنه أخذ مال بغير حق، كونه يستقدم العمال، لا ليعملوا عنده، ولكن ليعملوا عند غيره، ويعطوه مقابل استقدامهم، وكفالتهم شيء من المال، فهذا محل نظر، وظاهر كلام أهل العلم منع ذلك، ولم أر في كلام أحد من أهل العلم ما يدل على جواز ذلك. وقد بحثنا هذا في هيئة كبار العلماء، ودرس ذلك دراسة وافية، ولم يتضح في كلام أهل العلم ما يدل على جواز هذا العمل، لكن إذا استقدمه ليعمل عنده بأجر معلوم بالبناء في الزراعة، في كذا، في أجر معلوم، لا بأس، لكن لا ينبغي له أن يستقدم الكافر؛ فإن هذه الجزيرة لا يجوز أن يبقى فيها دينان. الرسول ﷺ أمر بإخراج المشركين من هذه الجزيرة، وإخراج اليهود، والنصارى منها، ولا يبقى فيها إلا دين واحد، وهو الإسلام، فإذا استقدم؛ فليستقدم مسلمًا، من إندونيسيا، من باكستان، من غير ذلك، يعمل، ويتحرى أن يكون مسلمًا طيبًا، يعينه على الشروط؛ لأن بعض المسلمين، بعضهم فيه شر كثير، لكن ينبغي لمن استقدم أحدًا أن يتحرى، ويسأل حتى لا يستقدم إلا مسلمًا طيبًا يعمل، وأما استقدامه ليستفيد منه ليوزعه على الناس؛ فهذا يسبب استقدام المفسدين، والفاسدين، والأشرار، والكفار من أجل الطمع، ولا ينبغي ذلك، ولا نعلم في كلام أحد من أهل العلم ما يجوز ذلك.","link":"https://binbaz.org.sa/fatwas/1689/حكم-من-استقدم-عمالا-من-الخارج-واخذ-مالا-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_558.mp3","categories":["الإجارة"]},{"id":6291,"question":"جاءنا أكثر من سؤال من أحد الإخوة يتضررون من رفع الإيجارات عليهم؛ اعتمادًا على الفتوى التي وردت، وقالوا: إن هذا ظلم وقع عليهم، وغيرهم قد لا يكون مستعدًا لإخلاء المحل بسبب كثرة البضاعة التي عنده، فما الحيلة في ذلك؟","title":"ظاهرة رفع الإيجار في العقارات والمباني ودعوى التضرر","answer":"الجواب: الظالم من أخذ أموال الناس بغير حق، ما هو بالظالم من جعل... الظالم الذي يريد أن الدولة تجبر الملاك، أن يعطوا أموالهم بغير حق، هذا الظالم، أما إطلاق العقار فهو من حسنات الدولة، ونسأل الله أن يثبتها، وبعد ذلك تستقيم الأحوال.  مضى على الناس أربعة عشر قرنًا ما أجبروا على تأجير أملاكهم، كل يستأجر كما أمر الله وكما أذن الله  والذي عنده نزاع، أو إشكال ... بيته، أو دكانه؛ لأنه أحدث فيها أشياء، فالمحكمة تحكم بينه، وبين صاحبه. الرسول يقول: إن دماءكم، وأموالكم، وأعراضكم عليكم حرام، كحرمة يومكم هذا، في شهركم هذا في بلدكم هذا ويقول: كل المسلم على المسلم حرام، دمه، وماله، وعرضه ويقول سبحانه في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُواْ لاَ تَأْكُلُواْ أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ [النساء:29].  فمن الباطل أن يقول المستأجر: اذهب يا فلان، ما لك حق عندي، ويطرده عن بيته، وعن دكانه؛ لأن الدولة قالت له: خذه بكذا وكذا، فهذا هو الظلم، وهذا هو المنكر، لكن الناس إذا اعتادوا الباطل، وإذا اعتادوا الفساد، وإذا اعتادوا التعدي على الناس؛ استحلوه، وصار الحق عندهم ظلمًا، وصار الظلم حلالًا، ومثل الذين إذا شربوا الخمر، واعتادوه ما يرضون أن أحدًا يمنعهم من الخمر، والذين اعتادوا الدخان ما يرضون أن أحدًا يمنعهم من الدخان؛ لأنهم اعتادوه، وصار سجية لهم، ما يرضون أن يمنعوا منه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1795/ظاهرة-رفع-الايجار-في-العقارات-والمباني-ودعوى-التضرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_634.mp3","categories":["الإجارة"]},{"id":6306,"question":"سؤال آخر حسب وروده إلينا، وما يتصل بموضوع الندوة، ما رأي سماحتكم في البيت الذي يوجد به سائق، وخادم نصراني، أو بوذي، وهذا خطر على الأسرة، فهل من كلمة تقدمونها في كل مناسبة؛ لأجل إنقاذ هذا المجتمع؟","title":"حكم استقدام الخدم الكفار","answer":"الجواب: وهذا أيضاً قد كتب عنه مرات كثيرة في الإذاعة، والصحافة، وكتب عنه هيئة كبار العلماء للمسؤولين، وبينوا أنه يجب منع هذا منعًا باتًا، وأن لا يستورد نصراني، ولا بوذي، ولا غير ذلك من الكفرة، لا سائق، ولا خادم، ولا غير ذلك؛ بل يجب الحذر من شرهم، ووجودهم في البلاد، ويجب أيضاً القضاء على العمال من الكفار، وألا يبقى إلا من تدعو الضرورة إليه، بصفة خاصة استثنائية للضرورة؛ كما أبقى النبي ﷺ العمال في خيبر للضرورة، ثم طردهم عمر بعدما أمر بإخراجهم من الجزيرة -عليه الصلاة والسلام-. فالحاصل: أن هذا قد صدرت فيه وصايا، وقرارات بالقضاء عليهم، ونسأل الله أن يتمم ذلك في وقت قريب، وأن يقضى على هذا كله. والواجب على المسلمين: أن يكونوا بأنفسهم حماة للدين، وبعيدين عن مضار المسلمين في استيراد الكفرة، لا سائقين، ولا خادمات، ولا خدم، ولا مربيات، بل يجب منع هذا كله، وإذا دعت الضرورة؛ فليكن ذلك من المسلمين، يستقدم مسلمات طيبات، أو مسلمين طيبين إذا دعت الحاجة إلى هذا، وليتحرى أيضًا ليس كل مسلم يدعي أنه مسلم، يكفي، بل لا بدّ من التحري في ذلك، وكثير من الناس يدعي أنه مسلم، وليس بمسلم، وهذا يكون أشد من النصراني، والكافر؛ لخبثه، وفسقه، وإلحاده، وهو يتظاهر بالإسلام كالمنافقين. فينبغي التحري في ذلك عند الحاجة من باكستان، من ماليزيا، من إندونيسيا، من أفريقيا، من كل مكان، يتحرى المسلم الطيبين، والمسلمات الطيبات عند الحاجة، والضرورة، ومهما أمكن من الاستيراد؛ فهو خير له، وأسلم. أما النصارى، والكفرة من سائر الكفار من بوذي، أو شيوعي، أو غير ذلك، فالواجب ترك ذلك، والحذر من ذلك، وأن لا يستورد كافرًا أبداً، ولا سيما هذه الجزيرة هذه الجزيرة العربية ممنوع إيجاد الكفار فيها، ممنوع استيرادهم إليها، النبي في آخر حياته -عليه الصلاة والسلام- وعند مفارقته الدنيا أوصى بإخراج اليهود، والنصارى، والمشركين من هذه الجزيرة، وأمر ألا يبقى فيها إلا مسلمًا؛ لأنها بلاد الإسلام، مهبط الوحي، منطلق المسلمين، والفاتحين، فلا يجوز أن يبقى فيها إلا المسلمون، ويجب أن يخرج منها الكافرون، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1905/حكم-استقدام-الخدم-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_688.mp3","categories":["الإجارة"]},{"id":6327,"question":"سؤال آخر حسب وروده إلينا، وما يتصل بموضوع الندوة، ما رأي سماحتكم في البيت الذي يوجد به سائق، وخادم نصراني، أو بوذي، وهذا خطر على الأسرة، فهل من كلمة تقدمونها في كل مناسبة؛ لأجل إنقاذ هذا المجتمع؟","title":"حكم استقدام الخدم الكفار","answer":"الجواب: وهذا أيضاً قد كتب عنه مرات كثيرة في الإذاعة، والصحافة، وكتب عنه هيئة كبار العلماء للمسؤولين، وبينوا أنه يجب منع هذا منعًا باتًا، وأن لا يستورد نصراني، ولا بوذي، ولا غير ذلك من الكفرة، لا سائق، ولا خادم، ولا غير ذلك؛ بل يجب الحذر من شرهم، ووجودهم في البلاد، ويجب أيضاً القضاء على العمال من الكفار، وألا يبقى إلا من تدعو الضرورة إليه، بصفة خاصة استثنائية للضرورة؛ كما أبقى النبي ﷺ العمال في خيبر للضرورة، ثم طردهم عمر بعدما أمر بإخراجهم من الجزيرة -عليه الصلاة والسلام-. فالحاصل: أن هذا قد صدرت فيه وصايا، وقرارات بالقضاء عليهم، ونسأل الله أن يتمم ذلك في وقت قريب، وأن يقضى على هذا كله. والواجب على المسلمين: أن يكونوا بأنفسهم حماة للدين، وبعيدين عن مضار المسلمين في استيراد الكفرة، لا سائقين، ولا خادمات، ولا خدم، ولا مربيات، بل يجب منع هذا كله، وإذا دعت الضرورة؛ فليكن ذلك من المسلمين، يستقدم مسلمات طيبات، أو مسلمين طيبين إذا دعت الحاجة إلى هذا، وليتحرى أيضًا ليس كل مسلم يدعي أنه مسلم، يكفي، بل لا بدّ من التحري في ذلك، وكثير من الناس يدعي أنه مسلم، وليس بمسلم، وهذا يكون أشد من النصراني، والكافر؛ لخبثه، وفسقه، وإلحاده، وهو يتظاهر بالإسلام كالمنافقين. فينبغي التحري في ذلك عند الحاجة من باكستان، من ماليزيا، من إندونيسيا، من أفريقيا، من كل مكان، يتحرى المسلم الطيبين، والمسلمات الطيبات عند الحاجة، والضرورة، ومهما أمكن من الاستيراد؛ فهو خير له، وأسلم. أما النصارى، والكفرة من سائر الكفار من بوذي، أو شيوعي، أو غير ذلك، فالواجب ترك ذلك، والحذر من ذلك، وأن لا يستورد كافرًا أبداً، ولا سيما هذه الجزيرة هذه الجزيرة العربية ممنوع إيجاد الكفار فيها، ممنوع استيرادهم إليها، النبي في آخر حياته -عليه الصلاة والسلام- وعند مفارقته الدنيا أوصى بإخراج اليهود، والنصارى، والمشركين من هذه الجزيرة، وأمر ألا يبقى فيها إلا مسلمًا؛ لأنها بلاد الإسلام، مهبط الوحي، منطلق المسلمين، والفاتحين، فلا يجوز أن يبقى فيها إلا المسلمون، ويجب أن يخرج منها الكافرون، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1905/حكم-استقدام-الخدم-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_688.mp3","categories":["الإجارة"]},{"id":6402,"question":"يقول الله تعالى: اتَّبِعُوا مَن لاَّ يَسْأَلُكُمْ أَجْراً [يس:21] إلى آخر الآية، واستدل البعض بهذه الآية، وغيرها بأنه لا يجوز تعليم الإسلام، أو تعليم القرآن بأجر، فما قول سماحتكم،  وما الصحيح في هذا القول؟","title":"حكم تعليم الإسلام والقرآن بأجر","answer":"الجواب: هذه في حق الرسل، فالرسل بعثهم الله لدعوة الناس إلى الحق، والخير، والهدى، وأن لا يأخذون على دعوتهم أجرًا من الناس؛ لأنهم لو أخذوا أجرًا اتهموا بأنهم قاموا بهذه الدعوة لأجل المال، فالرسل ممنوعون بأن يأخذوا أجرًا، فهم يعطون الناس ،ولا يأخذون منهم، ليعلموا أنهم ما جاؤوا ليأخذوا مالاً، وإنما جاؤوا للرسالة، والدعوة، والهداية، وأما الذين يعلموا الناس الخير، يعلموا القرآن يعلموهم العلم، إذا احتاج إلى ذلك؛ فلا بأٍس عليه. يعني ينحبس عليهم على تعليمهم، ويقتطع أوقاته في ذلك؛ فلا بأس أن يعطى ما يعينه على الأولاد، وتفقيههم، وتحفيظهم لكتاب الله عند جمهور من أهل العلم، ولا حرج في ذلك، وقد قال النبي ﷺ: إن أحق ما أخذتم عليه أجرًا كتاب الله وجعل أخذ الأجر على كتاب الله حق، ولما مر بعض الصحابة على طائفة من العرب، ورئيسهم لديغ، لدغته حية، وقد فعلوا كل شيء، فلم ينفعه، فقالوا لهم: هل فيكم من راق؟ قالوا: نعم،، ولكننا نزلنا عليكم، ولم تقرونا، ولم تضيفونا، فلا نقرأ عليه إلا بأجر، فاتفقوا معهم على قطيع من الغنم، ليرقون هذا اللديغ، فإن شفاه الله؛ يعطونهم القطيع، فقام إليه أحد الصحابة، وقرأ عليه فاتحة الكتاب، قرأ عليه، وتفل عليه؛ فأطلقه الله، وعافاه، فأعطوهم القطيع من الغنم، فقالوا: لا نأكله، ولا نتصرف في حقه، نأتي المدينة، ونسأل النبي -عليه الصلاة والسلام- فلما قدموا المدينة سألوا النبي، فقال: لا حرج، إن أحق ما أخذتم عليه أجرًا كتاب الله. فالمقصود أن هذا للعلاج، أو للتعليم لا بأس.","link":"https://binbaz.org.sa/fatwas/1971/حكم-تعليم-الاسلام-والقران-باجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_758.mp3","categories":["الإجارة","القرآن وعلومه"]},{"id":6428,"question":"إذا كنت أعمل في شغل، وأستلم على ذلك فلوسًا، ولكن صار عندي شغل، فطلبت من أحد أن يقوم بعملي هذا، ويأخذ نصف ما أستلمه، فهل هذا يجوز؟الشيخ: ماذا؟إذا كنت أعمل في شغل، وأستلم على ذلك فلوسًا، ولكن صار عندي شغل، فطلبت من آخر أن يقوم بهذا العمل، ويأخذ نصف المبلغ، وأنا النصف الآخر؟","title":"حكم من أقام غيره على عمل وإعطائه نصف الراتب","answer":"الجواب: إذا كان العمل المقصود وجوده، المقصود تحصيله، وأنت تستأجر بمن يقوم به على الوجه الذي تفعله أنت من جنسك، أو أطيب منك، أو أحسن منك؛ فلا بأس، إلا إذا كان المستأجر لك يريد مباشرتك، وقد اشترط أنك تباشره أنت بنفسك، أو يريد مباشرة بنفسك، وأن تولاه بنفسك، ليس لك أن تستأجر. أما إن كان لا ليس المقصود فيك إنما المقصود إيجاد هذا العمل، إيجاد هذه الحجرة، بناء هذه الحجرة، اصلاح هذا الباب، فتح هذه الفوه، وما أشبه ذلك مقصوده حين قاولك أن توجد هذا الشيء، ولو بغير نفسك، ولو بعامل آخر، فإذا استأجرت عاملاً يقوم بالمهمة مثلما تقوم بها أنت، أو أحسن منك؛ فلا حرج في ذلك بمثل ما أعطوك، أو بأقل، أو بأكثر.","link":"https://binbaz.org.sa/fatwas/2145/حكم-من-اقام-غيره-على-عمل-واعطاىه-نصف-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_793.mp3","categories":["الإجارة"]},{"id":6446,"question":"يقول: إن الذين وفدوا إلى المملكة من أهل الكفر بنسائهم، وأسرهم كثيرون، وأصبحوا يؤثرون في المواطنين تأثيرًا سيئًا للغاية، يعادل تمامًا الأثر الذي يحدثونه، فيمن يذهب إليهم من المبتعثين، فهلا أجبروا على الالتزام بتقاليد المملكة، وهي تعتقد الإسلامية في كل مظاهرهم .. أو لا يسمح لهم بالبقاء صيانة للدين، والمسلمين؟","title":"حكم استقدام الكفار إلى بلاد المسلمين","answer":"الجواب: هذا السؤال عظيم، ولكنه وارد، وأن الخطر الآن موجود، وعظيم، والتأثر بالكفار الموجودين أيضًا عظيم، وموجود، ولهذا وجه العلماء إلى الحكومة -وفقها الله- في إنهاء عقود الكفرة، وألا يقبل منهم كل من يضر المسلمين، وألا يستورد منهم إلا من تدعو الضرورة إليه، فيه صفات خاصة ضرورية؛ أما من سواه فينبغي إنهاء عقده، وينبغي ألا يبقى بين المسلمين لما في بقائه... غيره من المسلمين، إلا من تدعو الضرورة إليه بصفة خاصة، كما أن النبي ﷺ أقر اليهود في خيبر لما احتاج إليهم عمالًا في خيبر، ثم أجلاهم عمر بعدما أمر النبي بإجلائهم، عليه الصلاة والسلام. وهكذا لما اضطر إلى دليل من مكة يدله على المدينة؛ استأجر واحدًا .. يدله على المدينة و[كان] على دين قومه لما عرف أمانته، وأنه لا يضره في هذا السبيل. فالمقصود: أن هناك استثناءات لا بأس بها عند وجود شروطها، ولكن لا ينبغي للمسلم في كل مكان أن يرضى بهذه الحالة، وأن يستورد الكفار؛ طمعًا في الدنيا، هذا يستورد عمالًا، وهذا يستورد عمالًا، وهذا يستورد، وهذا يستورد من الكفار، ويحتجون بوجودهم عند هذه الدولة، هذا غلط، لا يجوز، لا يجوز استيراد عمالًا لا من الهند، ولا من باكستان، ولا من تايلاند، ولا من غيرها، ولا من الفلبين، لا يجوز استيراد العمال الكفار أبدًا، ولا شغالات عاملات كافرات.. أو مربيات، كل هذا منكر يجب القضاء عليه، ويجب التعاون ضده.  هكذا يجب على المسلمين أينما كانوا، ولا يحملهم الطمع في الأموال، أو الحرص على الخدمة، أو ما أشبه ذلك، يجب ألا يحملهم هذا على التساهل حتى يستوردوا الكفرة الذين يضرون المسلمين في بيوتهم، ويضرون أخلاقهم، ويضرون عقائدهم، ويضرون أسرهم، كل هذا معروف. فالواجب على المسلمين أينما كانوا في أي مكان: أن يحذروا هذا، وأن يكون استيرادهم عند الضرورة، يستوردوا المسلمين، يختارونهم، ويتبصرون في اختيارهم أيضًا، ولا يستوردون كل من هب ودب بدعوى الإسلام، بل يجب على من أراد شيئًا أن يعتني به، وأن يبعث من يختار المسلم المناسب المسلمة المناسبة عند الضرورة، ويذهب بنفسه حتى يتحقق، وحتى يسأل من يظن فيه الخير؛ حتى لا يستورد إلا مسلمًا طيبًا، أو مسلمة طيبة تنفع المسلمين، وتقوم بالعمل الذي يحتاجه المسلمون، ويقوم العامل كذلك المسلم بما يحتاجه المسلمون. فالمسلمون أولى بالنفع من أولئك، أولى بأن ينفعوا، وينفعوا أنفسهم، فهم إخواننا إذا استقاموا، هم إخواننا كوننا نستوردهم، وننفعهم بالمال، وحتى ينفعوا بلادهم.. فهم أولى من استيراد الكفرة عمالًا، أو غير عمال، والواجب على من له صلة بهذا من المؤسسات أن يخشى الله، وأن يراقب الله، وأن يحذر استيراد الكفار كيفما كانوا، وأن يحذر استيراد الخادمات، والمربيات الكافرات، بل يجب أن يحذر هذا كله، وأن يكون في ذلك مساعدًا للمسلمين، ومساعدًا للدولة في قلة الكفار، وفي تكثير المسلمين؛ حتى لا يبقى إلا المسلم، والمسلمة، وحتى يقل وجود الكفرة، أو يعدم بالكلية، نسأل الله العون على ذلك.","link":"https://binbaz.org.sa/fatwas/2185/حكم-استقدام-الكفار-الى-بلاد-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_810.mp3","categories":["الإجارة"]},{"id":6467,"question":"يقول: إن الذين وفدوا إلى المملكة من أهل الكفر بنسائهم، وأسرهم كثيرون، وأصبحوا يؤثرون في المواطنين تأثيرًا سيئًا للغاية، يعادل تمامًا الأثر الذي يحدثونه، فيمن يذهب إليهم من المبتعثين، فهلا أجبروا على الالتزام بتقاليد المملكة، وهي تعتقد الإسلامية في كل مظاهرهم .. أو لا يسمح لهم بالبقاء صيانة للدين، والمسلمين؟","title":"حكم استقدام الكفار إلى بلاد المسلمين","answer":"الجواب: هذا السؤال عظيم، ولكنه وارد، وأن الخطر الآن موجود، وعظيم، والتأثر بالكفار الموجودين أيضًا عظيم، وموجود، ولهذا وجه العلماء إلى الحكومة -وفقها الله- في إنهاء عقود الكفرة، وألا يقبل منهم كل من يضر المسلمين، وألا يستورد منهم إلا من تدعو الضرورة إليه، فيه صفات خاصة ضرورية؛ أما من سواه فينبغي إنهاء عقده، وينبغي ألا يبقى بين المسلمين لما في بقائه... غيره من المسلمين، إلا من تدعو الضرورة إليه بصفة خاصة، كما أن النبي ﷺ أقر اليهود في خيبر لما احتاج إليهم عمالًا في خيبر، ثم أجلاهم عمر بعدما أمر النبي بإجلائهم، عليه الصلاة والسلام. وهكذا لما اضطر إلى دليل من مكة يدله على المدينة؛ استأجر واحدًا .. يدله على المدينة و[كان] على دين قومه لما عرف أمانته، وأنه لا يضره في هذا السبيل. فالمقصود: أن هناك استثناءات لا بأس بها عند وجود شروطها، ولكن لا ينبغي للمسلم في كل مكان أن يرضى بهذه الحالة، وأن يستورد الكفار؛ طمعًا في الدنيا، هذا يستورد عمالًا، وهذا يستورد عمالًا، وهذا يستورد، وهذا يستورد من الكفار، ويحتجون بوجودهم عند هذه الدولة، هذا غلط، لا يجوز، لا يجوز استيراد عمالًا لا من الهند، ولا من باكستان، ولا من تايلاند، ولا من غيرها، ولا من الفلبين، لا يجوز استيراد العمال الكفار أبدًا، ولا شغالات عاملات كافرات.. أو مربيات، كل هذا منكر يجب القضاء عليه، ويجب التعاون ضده.  هكذا يجب على المسلمين أينما كانوا، ولا يحملهم الطمع في الأموال، أو الحرص على الخدمة، أو ما أشبه ذلك، يجب ألا يحملهم هذا على التساهل حتى يستوردوا الكفرة الذين يضرون المسلمين في بيوتهم، ويضرون أخلاقهم، ويضرون عقائدهم، ويضرون أسرهم، كل هذا معروف. فالواجب على المسلمين أينما كانوا في أي مكان: أن يحذروا هذا، وأن يكون استيرادهم عند الضرورة، يستوردوا المسلمين، يختارونهم، ويتبصرون في اختيارهم أيضًا، ولا يستوردون كل من هب ودب بدعوى الإسلام، بل يجب على من أراد شيئًا أن يعتني به، وأن يبعث من يختار المسلم المناسب المسلمة المناسبة عند الضرورة، ويذهب بنفسه حتى يتحقق، وحتى يسأل من يظن فيه الخير؛ حتى لا يستورد إلا مسلمًا طيبًا، أو مسلمة طيبة تنفع المسلمين، وتقوم بالعمل الذي يحتاجه المسلمون، ويقوم العامل كذلك المسلم بما يحتاجه المسلمون. فالمسلمون أولى بالنفع من أولئك، أولى بأن ينفعوا، وينفعوا أنفسهم، فهم إخواننا إذا استقاموا، هم إخواننا كوننا نستوردهم، وننفعهم بالمال، وحتى ينفعوا بلادهم.. فهم أولى من استيراد الكفرة عمالًا، أو غير عمال، والواجب على من له صلة بهذا من المؤسسات أن يخشى الله، وأن يراقب الله، وأن يحذر استيراد الكفار كيفما كانوا، وأن يحذر استيراد الخادمات، والمربيات الكافرات، بل يجب أن يحذر هذا كله، وأن يكون في ذلك مساعدًا للمسلمين، ومساعدًا للدولة في قلة الكفار، وفي تكثير المسلمين؛ حتى لا يبقى إلا المسلم، والمسلمة، وحتى يقل وجود الكفرة، أو يعدم بالكلية، نسأل الله العون على ذلك.","link":"https://binbaz.org.sa/fatwas/2185/حكم-استقدام-الكفار-الى-بلاد-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_810.mp3","categories":["الإجارة"]},{"id":6518,"question":"نرجو منك أن توضح لي ولجميع الحاضرين حلية المال بالنسبة للعمل، فمن شروط استجابة الله دعاء العبد أن يكون مطمعه، وملبسه حلالًا، والمشاهد أن معظمنا من الموظفين في الدوائر الحكومية قد يحصل من الشخص أن يتأخر عن حضور بداية الدوام، أو الذهاب مثلًا الساعة الثانية في بعض المصالح الحكومية، والخروج من العمل أثناء الدوام لقضاء بعض الأعمال، بعد استئذان رئيس القسم، وليس الرئيس المباشر، أو بدون استئذان، قد يكون كسلاناً، وقد يكون ليس لديه الراحة الكاملة، حيث بعض الموظفين قد يغفو في المكتب بعض الأحيان، أي ينام، فما رأي فضيلتكم؟","title":"الواجب على الموظف تجاه وظيفته","answer":"الجواب: لا ريب أن الواجب على العامل أن يؤدي العمل بأمانة، العامل أخذ الأجرة في مقابل عمله، سواء كان موظفًا في دائرة حكومية، أو في غير ذلك، الواجب على العامل أن يجتهد في أداء العمل، وأن يحفظ الوقت الذي تمت الإجارة على العمل فيه، هذا هو الواجب عليه.  فإذا فرط في شيء من ذلك في أسباب اقتضت ذلك من عارض منعه من شيء من ذلك، أو نوم منعه من ذلك، ولم يتعمد ذلك، فنرجو أن يكون ذلك ... العفو، ولا يضره ذلك -إن شاء الله- ولا يضر مطمعه، ولكن لا ينبغي أن يتعمد التكاسل والتساهل بهذه الأمور إذا تأخر كثيرًا، أو يخرج قبل الوقت من غير مبالاة، هذا كله خطر عظيم في دينه من جهة الإثم، ومن جهة المصدر أيضًا، فإنه لم يؤد الحق الذي يستحل به المكسب، وهو الأجرة.  فالواجب تقوى الله في ذلك، وأن يحذر التساهل مهما أمكنه، وأن يتقي الله ما استطاع، وما فات من ذلك من الشيء اليسير ... بأعذار عارضة فنرجو أن يعفو الله عنه سبحانه.","link":"https://binbaz.org.sa/fatwas/2265/الواجب-على-الموظف-تجاه-وظيفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_888.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":6581,"question":"ما حكم راتب الموظف الذي يتساهل في عمله، ولا يؤديه على الوجه الأكمل؟ هل هو يصبح حرامًا، أم حلالًا؟","title":"حكم راتب الموظف المتساهل في عمله","answer":"الجواب: راتبه فيه شبهة، ينبغي له أن يتقي الله، وأن يعتني بعمله حتى لا يكون في راتبه شبهة؛ لأن الواجب عليه أن يؤدي الحق الذي عليه؛ حتى يستحل الراتب، فإذا كان لا يبالي؛ فراتبه على كل حال بعضه حرام، فينبغي له أن يحذر، ويتقي الله جل وعلا.","link":"https://binbaz.org.sa/fatwas/2428/حكم-راتب-الموظف-المتساهل-في-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_955.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":6738,"question":"نرى ظاهرة خطيرة وهي: استقدام المربيات غير المسلمات في تربية الأولاد، فينتج عن ذلك الضرر الكثير، نرجو إبداء النصيحة للمسلمين، وجزاكم الله خيرًا؟","title":"خطر استقدام المربيات الكافرات والفاسقات","answer":"الجواب: استقدام المربيات من الكافرات، والفاسقات من أعظم الشر، ومن أعظم البلاء، وقد صدر تعميم من وزير الداخلية في منع ذلك، وألا يستقدم هؤلاء، ولكن نسأل الله أن يمن بالتنفيذ.  المقصود: أن استقدام الكافرات مطلقًا أمر ممنوع، الكافرات لا يجوز استقدامهن إلى هذه البلاد، لا مربية، ولا خادمة، ولا غير ذلك، وهكذا الكفار من السائقين، والخدم، والعمال لا يجوز استقدامهم أبدًا.  فالرسول ﷺ أمر بإخراج المشركين من الجزيرة، لا يهود، ولا نصارى، ولا غيرهم، أمر بإخراجهم، وأوصى بإخراجهم عند موته -عليه الصلاة والسلام- وقال: إن هذه الجزيرة لا يجوز أن يبقى فيها إلا مسلم، هذا معنى كلامه -عليه الصلاة والسلام- يجب ألا يبقى فيها إلا مسلم؛ لأنها مهد الإسلام، وهي مطلع النور، وشمس الرسالة، فلا يجوز أن يبقى فيها دينان، نهى أن يبقى فيها دينان -عليه الصلاة والسلام- وأمر بإخراج الكفار.  فالواجب على الدولة، وعلى المسلمين، أن يتعاونوا في عدم استقدام الكفرة، واستقدام المربيات، والخادمات شره كبير إذا كن كافرات، وهكذا إذا كن فاسقات، وإذا كان ولا بد فلتكن مسلمة مستقيمة، إذا دعت الحاجة إلى .. أما الكافرة فلا.  وهكذا العامل الكافر، السائق الكافر لا يجوز استقدامه، هناك مسلمون ممكن الاستعانة بهم، واستقدامهم للحاجة، ولكن أكثر الخلق لا يبالي، ولا يهمه هذا الأمر، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2613/خطر-استقدام-المربيات-الكافرات-والفاسقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1109.mp3","categories":["الإجارة"]},{"id":6805,"question":"ما رأيكم في ... على خير، وشخص من أبناء الإسلام..؟الشيخ: كيف؟الطالب: ما رأيكم في أهل الأموال .. غير الذي على دين الإسلام وابن الإسلام ..؟","title":"نصيحة لأصحاب الأعمال باستقدام العمال المسلمين","answer":"الجواب: الله يهديهم، ما ينبغي هذا، ينبغي أن يستقدم المسلمون للخدمة، والأعمال.\nأما في الجزيرة ما يجوز، في الجزيرة العربية لا يجوز استقدام الكفار أبدًا، بل يستقدم لها المسلمون من الأعمال كلها عند الحاجة، وأما الكفار لا يستقدمون، وهكذا في البلاد الأخرى، في مصر، والشام، والعراق، وغيرها، إذا وجد المسلمون فهم أولى بالعمل من الكفار، والكافر إذا احتيج إليه في عمل يذله، ولا يرفع رأسه، في عمل يراعى فيه، وينفع المسلمين؛ لا بأس، النبي ﷺ استأجر الكفار في خيبر في الحرث، والزرع، واستأجر خادمًا في الطريق، يدله الطريق إلى المدينة، فإذا دعت الحاجة إليهم في استخدامهم في غير الجزيرة العربية؛ فلا بأس، أما في الجزيرة فلا، والمسلمون مقدمون على كل حال.","link":"https://binbaz.org.sa/fatwas/2693/نصيحة-لاصحاب-الاعمال-باستقدام-العمال-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1191.mp3","categories":["الإجارة"]},{"id":6822,"question":"ما رأيكم في ... على خير، وشخص من أبناء الإسلام..؟الشيخ: كيف؟الطالب: ما رأيكم في أهل الأموال .. غير الذي على دين الإسلام وابن الإسلام ..؟","title":"نصيحة لأصحاب الأعمال باستقدام العمال المسلمين","answer":"الجواب: الله يهديهم، ما ينبغي هذا، ينبغي أن يستقدم المسلمون للخدمة، والأعمال.\nأما في الجزيرة ما يجوز، في الجزيرة العربية لا يجوز استقدام الكفار أبدًا، بل يستقدم لها المسلمون من الأعمال كلها عند الحاجة، وأما الكفار لا يستقدمون، وهكذا في البلاد الأخرى، في مصر، والشام، والعراق، وغيرها، إذا وجد المسلمون فهم أولى بالعمل من الكفار، والكافر إذا احتيج إليه في عمل يذله، ولا يرفع رأسه، في عمل يراعى فيه، وينفع المسلمين؛ لا بأس، النبي ﷺ استأجر الكفار في خيبر في الحرث، والزرع، واستأجر خادمًا في الطريق، يدله الطريق إلى المدينة، فإذا دعت الحاجة إليهم في استخدامهم في غير الجزيرة العربية؛ فلا بأس، أما في الجزيرة فلا، والمسلمون مقدمون على كل حال.","link":"https://binbaz.org.sa/fatwas/2693/نصيحة-لاصحاب-الاعمال-باستقدام-العمال-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1191.mp3","categories":["الإجارة"]},{"id":6852,"question":"لو عمل هذا المفتي بشيء من الأعمال، كقسمة المواريث، وطلب عليها الأجر، فهل يكون ذلك مباحًا له؟","title":"حكم أخذ الأجرة على الفتوى","answer":"الجواب: هذا يختلف، فيه تفصيل، هذا يختلف إذا كان المفتي له ما يقوم بحاله، ويغنيه عن الناس من بيت المال، أو من الأوقاف، أو من أهل القرية، فليس له أن يأخذ شيئًا، بل عليه أن يفتيهم، ويبين لهم قسمة المواريث، هذا له كذا، وهذا له كذا، وهذا له كذا.  أما إذا كان فقيرًا، قد تفرغ لأعمالهم، فقد ذكر العلماء أنه لا بأس أن يشرط عليهم شيئًا معلومًا، لكن ليس فيه محاباة لأحد، حتى يقوم بحاله، يعني كل فتوى يكون له درهم، وكل حكم فيه درهم، أو درهمين، أو كذا. هذا ذكره بعض أهل العلم، والورع تركه مهما أمكن، وإلا نص بعض أهل العلم على أنه يجوز للحاكم، والمفتي أن يضع شيئًا معلومًا، يستعين به على حاجاته، ومؤنته إذا اضطر إلى ذلك، وليس له راتب من بيت المال، ولا من الأوقاف، ولا من أي جهة، وهو محتاج إلى هذا الشيء، وليس له كسب. قد ذكر جمع من أهل العلم: أنه يجوز أن يفرض شيئًا معلومًا على المتخاصمين، لا يحابي أحدًا، أو على المستفتين، كل من جاء للفتوى يكون عليه كذا، فهذا في الحقيقة أمر خطير، وإذا تيسر الورع عنه، والبعد عنه بأي وسيلة؛ فهو خير للمؤمن، وخير للمفتي.","link":"https://binbaz.org.sa/fatwas/2728/حكم-اخذ-الاجرة-على-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1228.mp3","categories":["الإجارة"]},{"id":6870,"question":"ما مدى صحة حديث: أعطوا الأجير أجره قبل أن يجف عرقه؟","title":"درجة حديث: «أعطوا الأجير أجره»","answer":"الجواب: هذا ضعيف، حديث ضعيف، لكن يغني عنه حديث آخر صحيح يقول النبي ﷺ: يقول الله: ثلاثة أنا خصمهم يوم القيامة، ومن كنت خصمه خصمته، رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا فاستوفى منه، ولم يعطه أجره. الواجب يعطى أجره، ولكن كونه يبادر قبل أن يجف عرقه، هذا الحديث ضعيف. والظاهر البدار بإعطائه إياه، ولو بعد ما جف عرقه.","link":"https://binbaz.org.sa/fatwas/2758/درجة-حديث-اعطوا-الاجير-اجره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1250.mp3","categories":["الإجارة","الرقى والتمائم"]},{"id":6927,"question":"وفي نفس الورقة سؤال نفس الأخ يقول: نحن ننتظر هذا اللقاء من الأسبوع إلى الأسبوع؛ لنطرح عليكم ما يلفت أنظارنا من أمور خطيرة جدًا، ومن ضمنها استقدام الكفرة في البلاد بشكل عجيب جدًا بطرق الاحتيال، والأدهى من ذلك هو أن بعض الأفراد السعوديين الذين هم يسعون، ويبذلون الجهد في استقدامهم، وبذلك تتيسر لهم الإجراءات، في حين أن مكتب الاستقدام رفض ويرفض استقدام أهل بعض المسلمين؛ بحجة التعليمات الأخيرة، التي لم تنشر حتى الآن، بالرغم من أن الجميع يعلم تمام العلم بأن الكفرة المبشرين يأتون إلى بلادنا؛ لعرض ما لديهم، والتأثير على ضعاف النفوس في شتى المجالات، نرجو من فضيلتكم بإرشاد الجهات المختصة باستقدام المسلمين، بدلًا من الكفرة، وجزاكم الله عنا خير الجزاء.","title":"خطر استقدام العمال الكفار","answer":"الجواب: هذا شيء مبذول فيه الجهود، وهذا شيء قد بذل فيه الجهود منا، ومن غيرنا -ونسأل الله أن ينفع بالأسباب- لا شك أن استقدام الكفرة من المصائب العظيمة، من المنكرات الظاهرة. فالواجب على الشاب: أن يكون حريصًا على دينه، بعيدًا عن استقدام الكفرة، يجب على المسلم أن يبتعد عن استقدام الكفرة، وإذا كانت هناك حاجة إلى استقدام عمال؛ فليستقدم مسلمين، لا كفرة. والدولة -نسأل الله لها التوفيق- كذلك عندها معلومات عن هذا كافية، وقد وعدت بالعناية بهذا الأمر، وألا يستقدم إلا من تدعو له الضرورة، ولكن نسأل الله أن يعينها ويرزقها البطانة الصالحة، ويعين الشعب على مساعدتها في الخير؛ حتى لا يستقدموا الكفرة، وحتى لا يطلبوا استقدام الكفرة -نسأل الله العافية-. ثم أيضًا هناك -بلغتنا أيضًا- وهو أنه يوجد ناس يكتبون في الجوازات: أنهم مسلمون، وهم كفار، يكذبون، فينبغي التحرز من هذا، وألا يستقدم إلا أناسًا معروفين، يكون له وكيل، أو مبعوث جيد، يسأل عنه المسلمين الطيبين، لا عن الذين يتسمون بالإسلام، وهم كذبة، أو مسلمين بالدعوى، والاسم مع تركهم الصلوات، وشربهم المسكرات، يحذر هؤلاء؛ ليحرص إذا كان مضطرًا إلى استقدام عمال يشترط على استقدام مسلمين معروفين بين أهل بلادهم بالإسلام. وهكذا مثل استقدام السائق، أو استقدام خادم، أو خادمة كل هذا يجب فيه الحذر، وألا يستقدم إلا من عرف بالإسلام والاستقامة، والسيرة الحميدة، وإلا فليدع، وليستعن بالله على العافية من أعمال هؤلاء، يستعن بالله، وليصبر على ما يحصل له من مشقة؛ لئلا يقع في هذه البلية، وهي استقدام الكفرة.","link":"https://binbaz.org.sa/fatwas/2854/خطر-استقدام-العمال-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1302.mp3","categories":["الإجارة"]},{"id":6930,"question":"ما حكم أخذ الأجرة على تلاوة القرآن، وعلى تعليم القرآن؟ وما حكم تلاوته على الميت؟","title":"حكم أخذ الأجرة على تلاوة القرآن وتعليمه وقراءته على الأموات","answer":"الجواب: هذا فيه تفصيل: أما التلاوة فقد ذكر غير واحد إجماع العلماء على تحريم أخذ الأجرة على التلاوة، كونه يقول: اقرأ لي كذا بكذا وكذا، أو اقرأ للميت بكذا وكذا، هذا لا يجوز، لا يجوز التعاقد على التلاوة بجزء، أو جزئين لفلان، أو الميت فلان، هذا لا يجوز. أما التعليم فلا بأس على الصحيح، كونه يتعاقد مع إنسان يعلم في مدرسة، أو يدرس في مدرسة للطلبة بشيء معلوم كل شهر؛ لا بأس؛ لأنه محتاج إلى هذا الشيء، والنبي ﷺ قال: إن أحق ما أخذتم عليه أجرًا كتاب الله فالتعليم، والقراءة على المرضى، هذا لا بأس بالأجرة فيه، أما مجرد التلاوة لا.  السؤال: قراءته على الأموات؟ الجواب: أما قراءته على الأموات ما تجوز، الميت إذا مات انتهى، ما يسمع القرآن، ولا ينتفع بالقرآن، لكن يدعى له بالمغفرة والرحمة، يدعى له، ويتصدق عليه، ما في بأس، أما كونه يقرأ عليه، أو يقرأ للميت هذا ما ورد في النصوص، بعض أهل العلم قالوا: أنه إذا قرأ وثب له؛ لا بأس، لكنه قول ليس عليه دليل. فالأولى: ترك ذلك، ولكن يدعو له بالخير، والرحمة، والمغفرة، يتصدق عنه، هذا هو الذي أجمع العلماء على أن الميت ينتفع بالصدقة، وبالدعاء. وكذلك ينتفع إذا قضي عنه دينه، ينتفع بذلك إذا حج عنه، إذا أودي عنه الصيام الذي مات وهو لم يصمه، وعافاه الله، ولم يصم، وفرط، وصام عنه، كل هذا ينفع. السؤال: وعند الاحتضار؟ الجواب:قراءة القرآن تنفع عند الاحتضار؛ لأنه يعي ويفهم. السؤال:بالنسبة للمنطقة الغربية الثلاثة الأيام كلها يقرأون فيها على الميت؟ الجواب: الله يهدي الجميع، قد كتبنا كتابات كثيرة -نسأل الله-.","link":"https://binbaz.org.sa/fatwas/2860/حكم-اخذ-الاجرة-على-تلاوة-القران-وتعليمه-وقراءته-على-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1308.mp3","categories":["الإجارة","القرآن وعلومه"]},{"id":7081,"question":"لقد قدمت إلى هذه الديار الطبية منذ أكثر من خمس سنوات، ولقد عانيت، وتعبت غاية التعب في أول الأمر، ولم يكن عند كفيلي أي عمل يخرجني مما أنا فيه من ضيق وحاجة للمال؛ لتسيير به حياتي، وأنفق على أهل بيتي من الوالدين والإخوان، وبحثت عن عمل، وتنقلت في أكثر من أربعة مؤسسات تجارية، وأخيرًا استقر بي المقام في أحد المصارف هنا في الرياض، ولقد بذلت غاية جهدي، وأخلصت في عملي؛ حتى صرت محاسبًا في الحسابات الجارية، فعلمت أن هذا المصرف يضع أكثر ماله في بنوك داخل المملكة وخارجها بالفائدة الربوية، وهناك حسابين لعملاء تأتينا الأوراق المصرفية بتسجيل فائدة ربوية لحساباتهم طرفنا، وهي من بنوك خارجية، ويعلم الله تعالى أني في غاية الضيق لهذا الأمر، ولم يهدأ لي بال منذ أن عرفت هذا الأمر، علمًا بأني قد تزوجت، وأحضرت زوجتي، ورزقني الله تعالى بولدين، وأنا طالب علم شرعي إلى أن قال: وأحب الفقه في الدين، وأحضر ندوات العلم، ويبين أنه لو ترك هذا العمل سيقع في ضيق، وفي حرج، وسيتأخر في الصرف على أهله وأبيه وأمه، فباله مشغول من ذلك، وينتظر من سماحتكم فتوى بهذا؟","title":"حكم العمل في البنوك الربوية لمن كان مضطرا","answer":"الجواب:\n\nالله -جل وعلا- أحل لعباده ما فيه نجاتهم، وقضاء حاجاتهم، وحرم عليهم ما يضرهم، فليس العبد مضطرًا إلى ما حرم الله عليه، بل عليه أن يسعى جهده في طلب الرزق من طريق الحلال، والتوظف في البنوك إعانة لهم على الإثم والعدوان، سواء كان محاسبًا أو كاتبًا أو غير ذلك، فالواجب على المؤمن أن يحذر ذلك، وأن يبتعد عن البنوك؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]\n\nفالتعاون مع البنوك، أو مع قطاع الطريق، أو مع السراق، أو مع الغشاشين، أو مع أصحاب الرشوة كله تعاون على الإثم والعدوان، فلا يجوز، وما قبضته قبل ذلك -قبل العلم- فلك ما سلف، وما كان بعد العلم فليس لك، يقول الله -جل وعلا-: فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275]. \n\nما قبضته سابقًا قبل أن تعلم فهو لك، وأما بعد أن علمت؛ فعليك أن تغادر هذا العمل، وتترك هذا العمل، وتبذل ما قبضته من طريق الربا، وأنت عالم في جهة البر والخير، كالصدقة على الفقراء والمساكين، إلى غيره؛ حتى تتخلص من هذا المال الذي جاءك بغير وجهه، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه لعن آكل الربا، وموكله، وكاتبه وشاهديه، وقال: هم سواء.\n\nفالواجب على المؤمن أن يحذر ذلك وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأنت إذا اتقيت الله؛ يسر الله أمرك، ورزقك من حيث لا تحتسب، فالتمس أعمالًا أخرى، ولو بأجر قليل، إذا كنت تأخذ من البنك خمسة آلاف، أو ستة آلاف، أو عشرة آلاف شهريًا؛ فسوف تجد -إن شاء الله- من الأعمال المباحة بمعاش يكفيك، ويبارك الله لك فيه، ولو ألفين، أو ثلاثة، أو أربعة، ولو أقل من ذلك بكثير.\n\nأنت عليك أن تطلب الحلال والله يعوضك، يقول النبي ﷺ في الحديث الصحيح لما سئل أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور وقال أيضًا: ما أكل أحد طعامًا أفضل من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/3085/حكم-العمل-في-البنوك-الربوية-لمن-كان-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1467.mp3","categories":["الربا والصرف","الإجارة"]},{"id":7306,"question":"إني استقدمت عمالاً من الخارج، واتفقت معهم أنهم يدفعون لي كل واحد خمسمائة ريالًا مقابل كفالتهم لمدة سنتين، وبعضهم يستفيد أكثر من الذي يدفعه، وبعضهم لا يحصل على شيء، فهل هذا حرام، أم لا؟","title":"حكم استقدام العمال بالكفالة وأخذ المال منهم","answer":"الجواب: هذه المسألة لم نر فيها من أهل العلم ما يدل على الجواز، وقد نظر فيها هيئة كبار العلماء، ورأوا فيها أنه ينبغي للمؤمن في مثل هذا ألا يستقدم إلا على الطريقة التي رسمتها الدولة، فإنها طريقة حكيمة، ويستقدمهم بأجرة معلومة بينه، وبينهم للعمل عنده، ويكونون مضبوطين من جهته، ويتحرى الناس الطيبين المعروفين بالخير؛ حتى لا يضر المسلمين.  فإذا استقدمهم على حسابه؛ شغلهم عندهن أو اتفق معهم على الشغل عند غيره بالراتب الذي اتفق معهم عليه، هذا لا بأس يشغلهم على حسابه ويعطيهم الراتب، وإذا تخلى عنهم، وصاروا يعملون لحسابهم، وهم مرضيون عنهم في أنفسهم على الطريقة التي رسمتها الدولة فلا بأس بذلك، أما أن يستقدمهم، ويأخذ منهم فلوسًا؛ لأجل الكفالة؛ فلا، هذا لا يصلح.","link":"https://binbaz.org.sa/fatwas/3374/حكم-استقدام-العمال-بالكفالة-واخذ-المال-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1692.mp3","categories":["الإجارة"]},{"id":7366,"question":"هل من كلمة هنا في هذا المقام لرد خطر استقدام الكفرة، أم أن اللوبي الماسوني يمنع هذا؟","title":"حكم استقدام الكفرة للعمل في بلاد المسلمين","answer":"الجواب: الواجب على المسلمين أن يستقدموا المسلمين، ويجب عليهم ألا يستقدموا الكفرة؛ لأن الرسول ﷺ أوصى بإخراج اليهود والنصارى من هذه الجزيرة، وأوصى بإخراج المشركين من هذه الجزيرة.  فالواجب على جميع المسلمين أن ينفذوا هذه الوصية، وأن لا يستقدموا عاملًا ولا خادمًا، ولا غير ذلك إلا من المسلمين، وهذا الواجب على ولاة الأمور أيضًا في هذه الجزيرة، ألا يستقدموا إلا المسلمين، إلا من تدعو الضرورة القصوى إلى وجوده؛ لعدم وجود بديل عنه من المسلمين.","link":"https://binbaz.org.sa/fatwas/3444/حكم-استقدام-الكفرة-للعمل-في-بلاد-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1751.mp3","categories":["الإجارة"]},{"id":7370,"question":"في بعض الناس يستقدمون من العمال أعدادًا، ويشرط على العامل أعطني في السنة أربعة آلاف، خمسة آلاف، وتقعد هنا تشتغل، لكن هو ما يشتغل عنده إطلاقًا، هل كسبه هذا حلال، أو حرام؟","title":"حكم اشتراط الكفيل أموالا على مكفوليه الذين لا يعملون عنده","answer":"الجواب: لا ما يصلح، هذا كونه يأخذ على كفالته واستقدامه، هذا من أسباب الشر على المسلمين، يجب أن يكون الاستقدام على الشروط المضبوطة التي رتبتها الدولة، ونظمتها الدولة، وهذا قد عرض على هيئة كبار العلماء، وقرروا هذا، وكتبوا للدولة بذلك، وأن يكون الاستقدام على الشروط المضبوطة التي نظمتها الدولة حتى لا يكثر المفسدون في الأرض.","link":"https://binbaz.org.sa/fatwas/3455/حكم-اشتراط-الكفيل-اموالا-على-مكفوليه-الذين-لا-يعملون-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1759.mp3","categories":["الإجارة"]},{"id":7372,"question":"إنني استلم راتبًا قدره ستة آلاف وخمسمائة ريالًا، ولكن العمل الذي أعمله قليل جدًا، ونفسي غير مرتاحة؛ لأن الدخل اليومي حوالي مئتان ريالًا وقد لا أعمل في ذلك اليوم شيئًا، فهل أترك العمل، أم ماذا؟ وأشعر أن دعائي لا يستجاب بسبب أكل هذا الراتب بدون مقابل عمل واضح؟","title":"حكم أخذ أجر كبير على عمل خفيف","answer":"الجواب:  إذا كنت تؤدي ما استأجرت له، ويسر الله لك عملًا ما فيه كلفة؛ فاحمد ربك على ذلك، إذا كان الله يسر لك عملًا خفيفًا، وقد طابت نفس المستعمل والمستأجر بهذا الأجر، تقول: أنا لا أريد الخفة، أريد الشدة، الحمد لله إذا استعملك بأجر يومي مئتي ريال، أو بألف ريال يومي على عمل خفيف عليك، هذا من فضل الله عليك، ما عليك فيه بأس، إذا كان ما فيه خيانة ولا شيء؛ قمت بالواجب.  فإذا جابك حارس للباب ويعطيك كل يوم مئتين، وأنت حارس متسريح ما يضرك في هذا، ما في بأس عليك، الحمد لله، وإذا جابك سواق وأعطاك ألف ريالًا، أو ألفين ريالًا وأنت ما تسوق في اليوم إلا مرة أو ببعض الأيام، ما تسوق، فالحمد لله، المقصود ما عليك بأس يا بني إذا أديت الواجب الذي شرط عليك، ما عليك ولو كان الأجر كبيرًا، هذا من فضل الله عليك، والحمد لله.  ولكن بقي شيء واضح وهو الذي يعمل زيادة على عمله المستأجر له، هذا الأصل فيه الحل، والإباحة، لكن قد يكون هناك أشياء تمنع من العمل، إذا كان عمله الإضافي يضر عمله الرسمي، هذا ينظر فيه، لا بد من النظر، قد تكون الدولة وظفت في هذا شيئًا أو عينت في هذا شيئًا.  المقصود: أنه إذا كان عمله الزائد لا يضر عمله الذي استقدم لأجله ما نعلم فيه مانعًا شرعًا، أما إذا كان عمله الزائد يضر عمله الذي قدم من أجله، يعني يعمل مثلًا عملًا كثيرًا يرهقه، فإذا جاء العمل الذي استقدم من أجله قال أنا تعبان خاوي، ما يكون هذا، لابد يكون عمله الزائد ما يضر عمله الذي استقدم من أجله.","link":"https://binbaz.org.sa/fatwas/3460/حكم-اخذ-اجر-كبير-على-عمل-خفيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1764.mp3","categories":["الإجارة"]},{"id":7375,"question":"هل يجوز أن يكون هناك فرق، واختلاف بين المسلمين في الأجرة وكان العمل متساويًا؟","title":"اختلاف الأجرة بين شخصين مع كون العمل متساوياً","answer":"الجواب: نعم نعم يجوز، يجوز أن يكون فرق، ليس الناس على حد سواء، واحد يقول: أنا ما أعمل إلا كذا، والآخر يقول: أنا سامح أعمل بكذا، يقال: لا، لا بد تساوى بذاك؟ لا، إذا كان عنده سواقين اثنين في سيارة واحدة يسوقونها، هذا له الليل، وهذا له النهار، أو هذا له ساعات، وهذا له ساعات، واحد يقول: ما أنا سائق عندك إلا بكذا، والثاني يقول: ما أنا سامح بأقل من ذلك، ما في بأس، هذا يعطى خمسمائة وهذا يعطى أربعمائة لا حرج.","link":"https://binbaz.org.sa/fatwas/3461/اختلاف-الاجرة-بين-شخصين-مع-كون-العمل-متساويا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1765.mp3","categories":["الإجارة"]},{"id":7376,"question":"هل يجوز للكفيل أن يسمح للعامل لديه أن يعمل لحسابه الخاص حسب طلبه مقابل إعطاء الكفيل مبلغًا معينًا شهريًا؟","title":"حكم تأجير الكفيل مكفوله إلى غيره مقابل مبلغ شهري","answer":"الجواب: لا ما يصلح، هذا ما يصلح، الواجب إذا كان ولا بد، يقدم على حسابه، ثم يستعمله بعد ذلك فيما يشاء بالشروط التي بينهما، كل شهر بكذا، كل شهر بكذا، يستعمل في جنس العمل الذي استقدمه له، أو في عمل يرضاه العامل، وصاحب الاستئجار في أي عمل مباح شرعًا، على الطريقة التي نظمتها الدولة، ووضحتها الدولة للمستقدمين للعمال.","link":"https://binbaz.org.sa/fatwas/3456/حكم-تاجير-الكفيل-مكفوله-الى-غيره-مقابل-مبلغ-شهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1760.mp3","categories":["الإجارة"]},{"id":7380,"question":"آمل أن تسمعوا اقتراحي هذا جزاكم الله خيرًا، ألمس بوضوح ظلم كثير من أصحاب الأعمال للعمال الذين يعملون لديهم من المسلمين وغير المسلمين، وقد مر على سماحتكم كثير من الحالات، فلماذا لا تنصفون هؤلاء العمال المساكين المظلومين، وذلك بكتابة للمسؤولين عن هذا الأمر؛ لإنقاذهم وإعطائهم رواتبهم أو رواتب معقولة مقبولة، ولا نقل توحيد الرواتب لتناسب العمل ذاته بصرف النظر عن جنسية العامل، أو هويته؟","title":"الأجرة على حسب الشرط بين العامل والمستأجر","answer":"الجواب: الواجب يا أخي مثل ما قال النبي ﷺ: المسلمون على شروطهم فإذا اتفقوا معهم على شروط؛ فالواجب على العامل أن ينفذ، والواجب على المستأجر أن يسلم الأجر، المسلمون على شروطهم، وليس على هوى زيد ولا عمرو، إذا اتفقا على شيء؛ فالواجب على العامل أن يتقي الله، وأن يؤدي الأمانة، والواجب على من استأجره أن يؤدي حقه، وقد سمعت الحديث يقول الله -جل وعلا-: ثلاثة أنا خصمهم يوم القيامة: رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا، فاستوفى منه ولم يعطه أجره نسأل الله العافية.  وعلى الدولة وفقها الله، وعلى أمير كل بلاد أن ينصفهم، فإذا لم تنصفهم؛ وجب أن يحالوا إلى المحكمة، وهذا هو الواقع، وقد اتصل بنا بعض الناس في هذا مرات كثيرة، وكتب معهم إلى المسؤولين لإنصافهم وإلزام المستأجر أن يؤدي الحق الذي عليه، أو يذهب معهم إلى المحكمة حتى تنظر في أمرهم، هذا ما في طريق إلا هكذا، إما أن ينصفهم من نفسه ويتقي الله، وإما أن يحال معهم إلى المحاكم، لهم ولغيرهم حتى تنظر في الدعوة. وليس كل من قال إن المستأجر ما أنصفني يكون صادقًا، قد يكون العامل كاذبًا، وقد يكون المستأجر كاذبًا، كلاهما غير معصوم، فإذا اختلفا وتنازعا، فإن تيسر من يصلح بينهما من المسلمين، ويزيل النزاع بينهما، ويتوسط بينهما؛ فهو مأجور فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ [الأنفال:1] فإن لم يتيسر من يصلح بينهما؛ فليس لهما إلا الرجوع إلى المحاكم مثل غيرهم حتى تنظر في دعوى هذا، ودعوى هذا.","link":"https://binbaz.org.sa/fatwas/3457/الاجرة-على-حسب-الشرط-بين-العامل-والمستاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1761.mp3","categories":["الإجارة"]},{"id":7387,"question":"إذا استخدم المتعاقد لعمل براتب قد يصل لربع راتب نظيره من الوطنيين، فهل هذا جائز من قبل الجهة المستقدمة لهذا المتعاقد؟ وهل يجوز أن يعمل ذلك المتعاقد عملًا إضافيًا بعد إتمامه العمل الذي استقدم من أجله براتب قد يعينه على المعيشة لضعف راتبه الأساسي، إضافة لكثرة أعبائه؟","title":"الأجور على حسب الشروط","answer":"الجواب: الأجور على حسب الشروط «فالمسلمون على شروطهم» يجوز أن يستقدم واحدًا بألف، وواحدًا بمئتين، ليس شرطًا أن تتساوى، وليس الناس بالخبرة ولا بالفهم ولا بالقدرة سواء، فالعمال يختلفون والموظفون يختلفون، فهم على ما استقدموا عليه، فإذا استقدمهم على خمسمائة واستقدم آخرين على ألف ما المانع؟ المسلمون على شروطهم، ما ظلمهم، جاؤوا باختيارهم على خمسمائة، على ألف، والآخر على كذا، والآخر على كذا.  قد يكون عنده عمال متنوعون، منهم بألف، ومنهم من هو بخمسمائة، ومنهم من هو بثلاثمائة، فليس في هذا حرج، المهم أن يكون بالرضا والاتفاق والشروط المسبقة حتى لا يقدم إلا على بصيرة، وليس من شرط ذلك أن يكونوا سواء في الأجر، حتى الموظفون الآن السعوديون ليسوا سواء، هذا له كذا وهذا له كذا. ثم الناس في علمهم وفي مؤهلاتهم وفي قدراتهم يختلفون، هكذا المستقدمون يختلفون في معلوماتهم، وفي قدراتهم وفي مؤهلاتهم، فليسوا على حد سواء، والعمدة في  هذا هو الاتفاق والشروط، المسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/3459/الاجور-على-حسب-الشروط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1763.mp3","categories":["الإجارة"]},{"id":7755,"question":"هذه الرسالة وردت من جمهورية اليمن الديمقراطية، وبعث بها المستمع محفوظ محمد البكري ، يقول فيها محفوظ: من عادات بلدي حينما يموت شخص يقرأ عليه الناس ما تيسر من القرآن الحكيم لمدة ثلاثة أيام، ويؤجر قريب الشخص المتوفى أحد الناس -بإيجاده قراءة القرآن- ويؤجره قراءة كتاب الله بمبلغ معين، ثم توهب وتهدى هذه القراءات إلى روح المتوفى، ما حكم هذه القراءة؟ وهل تصل إلى روح الميت؟ أثابكم الله.","title":"حكم قراءة القرآن بالأجرة وإهداء الأجر إلى المتوفى","answer":"الجواب: هذه قراءة بدعة لا أساس لها في الشرع، ولم يرد في الشرع ما يدل على استحبابها ولا جوازها، فالواجب تركها وعدم فعلها، ثم المستأجر أي ثواب له؛ لأنه لم يقرأ إلا بالأجرة، وقد أجمع العلماء على أنه لا يجوز الاستئجار على تلاوة القرآن، فالذي يستأجر ليتلو للميت أو للحي أي ثواب له وهو لم يقرأ لله إنما قرأ للأجرة! فأي شيء يهدى!\nالمقصود أن هذا منكر ولا يجوز، والمستأجر ليتلو قد أتى منكراً عظيماً ومحرماً بالإجماع، وليس له ثواب حتى يهدى، فلا يجوز فعل هذا بل المشروع الدعاء له وتعزية أهله، أما كونهم يرتبون الناس ليقرءون ويستأجرون الناس ليقرءون للميت ويهدى له ثواب ذلك فليس له أصل، والاستئجار على هذا منكر وباطل. نعم.","link":"https://binbaz.org.sa/fatwas/4958/حكم-قراءة-القران-بالاجرة-واهداء-الاجر-الى-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04405.mp3","categories":["البدع والمحدثات","الإجارة"]},{"id":8034,"question":"هذه الرسالة بعث بها المواطن حسن محمد ، يقول فيها: السلام عليكم ورحمة الله وبركاته، وبعد: أطرح بين أيديكم هذا السؤال وأرجو الإجابة على ذلك:أنا رجل أشغل وظيفة مؤذن بمسجد ولي مرتب من الأوقاف ويقال لي: إنك استلمت راتب فليس لك أجر. وأنا لا أرغب ذلك، وإنما أرغب الأجر أحسن من الراتب، يقول: علماً أني أنا في حاجة إلى هذا الراتب حيث ليس لي أي دخل آخر ولكن أفضل أجر الآخرة على أجر الدنيا والله يحفظكم ويرعاكم؟","title":"حكم أخذ الأجرة على الأذان","answer":"الجواب: ثبت عن النبي صلى الله عليه وسلم أنه قال لـعثمان بن أبي العاص لما سأله أن يكون إمام قومه قال: أنت إمامهم، واقتد بأضعفهم، واتخذ مؤذناً لا يأخذ على أذانه أجراً.\nفدل ذلك على أن المؤذن الذي يتبرع بالأذان ويتطوع به يريد ما عند الله أنه أفضل وأولى من غيره، لكن ذكر العلماء أن الذي يعطى من بيت المال ما يعينه على ذلك لا حرج عليه في ذلك ولا بأس عليه؛ لأن بيت المال للمصالح مصالح المسلمين، وهكذا الأوقاف التي يوقفها المسلمون على المؤذنين والأئمة لا حرج عليهم إذا أخذوا منها ما يعينهم على العمل الصالح، فإذا أخذت -أيها السائل- من بيت المال من وزارة الأوقاف ما يعينك فلا حرج عليك ونرجو أن يكون لك الأجر كاملاً؛ لأنك تأخذ شيئاً يعينك على هذا الواجب وعلى هذا العمل الصالح وربما لو تركت ذلك لتركت هذا العمل لالتماس الرزق.\nفالحاصل: أن المؤذن إذا دفع إليه ما يعينه على أداء الأذان لحاجته إليه فلا حرج عليه في ذلك؛ لأن الأذان يحبسه يحتاج منه إلى أوقات، فإذا أخذ ما يعينه على ذلك فلا حرج عليه في ذلك.\nلكن من وسع الله عليه وأحب أن يعمل من دون شيء من بيت المال فذلك أفضل وأكمل لأنه حينئذٍ تكون قربته كاملة ليس فيها شيء من النقص بل عمل عمله لله كاملاً من دون شائبة، أما من أخذ من بيت المال فلا حرج عليه؛ لأن بيت المال للمسلمين عامة ولا سيما المصالح كالأذان والإمامة وأشباه ذلك، وهكذا الأوقاف التي توقف على المؤذنين والأئمة هذه كلها من باب التعاون على البر والتقوى، ومن باب تسهيل أمور الإمامة والأذان لأنه ليس كل واحد يتفرغ لهذا الشيء، فإذا أمنت حاجته كان هذا أدعى إلى أن يلتزم ويقوم بهذا الأمر العظيم الواجب. نعم.\nالمقدم: لكن هذا الأجر الذي يساق اليوم للمؤذنين هل يدخل فيه هذا الحث الذي حث عليه الرسول صلى الله عليه وسلم وهؤلاء يأخذون من بيت مال المسلمين الآن؟\nالشيخ: الذي يظهر أنه غير داخل في هذا وأن النبي ﷺ أراد الذي يعني يؤاجر يعطيه يقول: لا أؤذن إلا بأجر يأخذ أجراً على ذلك، يعني: مشارطة بينه وبين أهل المسجد أو بينه وبين بعض الناس الآخرين فهذا هو الأقرب في ظاهر النص، أما الذي يعطاه من بيت المال كما يعطى المدرس ويعطى الإمام ويعطى المجاهدون فهو غير داخل في هذا إن شاء الله، لكن لا شك أن الذي يريد يعني ألا يأخذ شيئاً بالكلية وأن يتفرغ لهذا الشيء من جهة نفسه لأن الله قد أعطاه مالاً ووسع عليه فهذا أكمل في الإخلاص. نعم.","link":"https://binbaz.org.sa/fatwas/5657/حكم-اخذ-الاجرة-على-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08005.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8036,"question":"وأول ما نعرض من هذه الرسائل -يا فضيلة الشيخ- رسالة عبد الله الحميد الذي يسأل: عن أخذ الأجرة على تعليم القرآن الكريم؟","title":"أجرة الراقي ومعلم القرآن إعانة لا بأس بها","answer":"الجواب: الله سبحانه وتعالى أنزل القرآن الكريم ليعمل به وليتدبر ويتعقل كما قال عز وجل: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ [ص:29] ولم ينزله سبحانه للأكل به يقرأ ليعطى ويسأل به الناس، لا، إنما أنزل للعمل به وتعليمه الناس والأخذ بما فيه من الأوامر وترك النواهي، أنزل لهذا الأمر، ولهذا قال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] .. إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] الآية فهو أنزل ليعمل به ليتعقل ويتدبر ولم ينزل ليؤكل به وتطلب به الدنيا.\nلكن تعليم الناس للقرآن يحتاج إلى فراغ وإلى تعب وإلى صبر فجاز -على الصحيح- أن يعطى المعلم ما يعينه على ذلك، وليس هذا من التأكل بالقرآن ولكن هذا من الإعانة على تعليم القرآن، فإذا وجد من يعلم القرآن ويحتاج إلى مساعدة فلا بأس أن يعطى من بيت المال أو من أهل المحلة أو أهل القرية ما يعينه على ذلك، حتى يتفرغ وحتى يبذل وسعه في تعليم أبناء البلد أبناء القرية كتاب ربهم عز وجل، فهذا ليس من باب التأكل ولكن هو من باب الإعانة على هذا الخير العظيم حتى يتفرغ للتعليم وحتى يكفى المئونة.. حتى لا يحتاج إلى ضياع بعض الأوقات في طلب الرزق وطلب حاجة بيته وأهله، هذا كله من باب التعاون على البر والتقوى.\nوكذلك إذا قرأ على المريض يعطى أيضاً، إذا قرأ على المريض ورقاه فلا بأس أن يعطى لحديث: «إن أحق ما أخذتم عليه أجراً كتاب الله» ولقصة اللديغ الذي قرأ عليه بعض الصحابة واشترطوا جعلاً فأمضاه النبي عليه الصلاة والسلام.\nفالحاصل: أن إعطاء الطبيب الذي يقرأ على الناس الذي يعالج بالقراءة إعطائه شيء على هذا الأمر لا بأس به كما يعطى المعلم، وهذا كله من باب التعاون على ما ينفع الناس، فالمعلم ينفع الناس بتعليمهم وتوجيههم وإرشادهم، والذي يقرأ على المريض كذلك يحتاج إلى مساعدة حتى يتفرغ لهذا الأمر ويقرأ على هذا وهذا وهذا، وقد جعل الله في كتابه شفاء لمرض القلوب ومرض الأبدان، وإن كان أنزل في الأصل والأساس لإنقاذ القلوب وتطهيرها من الشرك والمعاصي وتوجيهها إلى الخير لكن الله جعل فيه سبحانه وتعالى أيضاً شفاء لأمراض الأبدان، جعل كتابه العظيم شفاء للقلوب شيء لكثير من أمراض الأبدان إذا استعمله المؤمن مخلصاً لله عز وجل عالماً أنه سبحانه هو الذي يشفي وأن بيده كل شفاء سبحانه وتعالى.\nفإذا أعطي المعلم ما يعينه وأعطي الراقي الذي يعالج الناس بالرقية ما يعينه فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5651/اجرة-الراقي-ومعلم-القران-اعانة-لا-باس-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08001.mp3","categories":["صلاة التطوع","الإجارة"]},{"id":8296,"question":"فضيلة الشيخ، يعقد السائل مُقارنةً أو مُوازنةً بين العمال من المسلمين وغير المسلمين فيقول: إن غير المسلمين هم من أهل الأمانة، وأستطيع أن أثق فيهم، وطلباتهم قليلةٌ، وأعمالهم ناجحةٌ، أما أولئك فهم على العكس تمامًا. فما رأيكم سماحة الشيخ؟","title":"حكم استقدام عمالاً كفرة وترك المسلمين","answer":"الجواب:\n\nهؤلاء ليسوا بمسلمين على الحقيقة، هؤلاء يدَّعون الإسلام، أما المسلمون في الحقيقة فهم أولى وأحق، وهم أكثر أمانةً، وأكثر صدقًا من الكفار.\n\nوهذا الذي قلتَه غلطٌ، لا ينبغي أن تقوله، والكفار إذا صدقوا عندكم وأدوا الأمانة حتى يُدركوا مصلحتهم معكم، وحتى يأخذوا الأموال عن إخواننا المسلمين، فهذه لمصلحتهم، فهم ما أظهروا هذا لمصلحتكم، ولكن لمصلحتهم هم؛ حتى يأخذوا الأموال، وحتى ترغبوا فيهم.\n\nفالواجب عليكم ألا تستقدموا إلا الطيبين من المسلمين، وإذا رأيتم مسلمين غير مُستقيمين فانصحوهم ووجِّهوهم، فإن استقاموا وإلا فردُّوهم إلى بلادهم، واستقدموا غيرهم، وطالبوا الوكيل الذي يختار لكم أن يختار الناس الطيبين المعروفين بالأمانة، المعروفين بالصلاة، المعروفين بالاستقامة، لا يستقدم مَن هبَّ ودَبَّ.\n\nوكثيرٌ من الناس يدَّعي الإسلام وهو كافرٌ، ليس بمسلمٍ: كالمنافقين، ولكن أنتم أرباب الأعمال عليكم أن تستقدموا الطيبين، ولا تغتروا بهؤلاء الكفرة الذين يتصنعون عندكم ويُظهرون عندكم ما يُرغِّبكم فيهم من أمانةٍ، وصدقٍ، ونحو ذلك.\n\nفهذا لا ينبغي منكم، بل إخوانكم المسلمون أولى بأموالكم، وأولى بخدمتكم، وإذا حصل منهم نقصٌ فوجِّهوهم، وعلِّموهم، ولاحظوهم حتى يستقيموا.\n\nوهذا لا شك أنه من خداع الشيطان أن يقول لكم: إن هؤلاء الكفار أحسن من المسلمين، أو أكثر أمانةً، أو كذا، أو كذا. كله لما يعلمه عدو الله وجنوده من الشر العظيم في استقدام الكفرة واستخدامهم بدل المسلمين؛ فلهذا يُرغِّب فيهم، ويُزين لكم استقدامهم؛ حتى تدعوا المسلمين، وحتى تستقدموا أعداء الله؛ إيثارًا للدنيا على الآخرة، ولا حول ولا قوة إلا بالله.\n\nوقد بلغني عن بعضهم أنه يقول: إن المسلمين يُصلون ويُعطلون الأعمال بالصلاة، والكفار لا يُصلون؛ حتى يأتوا بأعمالٍ أكثر.\n\nوهذا أيضًا من جنس ما قبله، ومن البلاء العظيم أن يعيب المسلمين بالصلاة، ويستقدم الكفار؛ لأنهم لا يُصلون، فأين الإيمان؟! وأين التقوى؟! وأين خوف الله؟! أن تعيب إخوانك المسلمين بالصلاة!\n\nنسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/6109/حكم-استقدام-عمالا-كفرة-وترك-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10804.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8457,"question":"هنا رسالة اشترك في وضع أسئلتها مجموعة من إخواننا المصريين المقيمين في العراق وهم:أخونا: حسن مصري الجنسية، وأيضاً أحد الإخوة من هناك: ورمز إلى اسمه (م. أ. ع) والثالث: أيضاً يقول: (ع. ب. س) يسألون سماحة الشيخ! كما قلت مجموعة من الأسئلة ومن بينها سؤال عن أخذ الأجرة على تحفيظ القرآن الكريم حيث أن لديهم إمام في قريتهم في مصر ويأخذ أجراً على تحفيظ الصبيان للقرآن الكريم فبم توجهونهم لو سمحتم سماحة الشيخ؟","title":"حكم أخذ الأجرة على تحفيظ الصبيان القرآن؟","answer":"الجواب: لا حرج في ذلك، الصحيح أنه لا حرج في أخذ الأجرة على تعليم القرآن وتعليم العلم؛ لأن الناس في حاجة إلى التعليم؛ ولأن المعلم قد يشق عليه ذلك ويعطله التعليم عن الكسب، فإذا أخذ أجرة على تعليم القرآن أو تحفيظ القرآن أو تعليم العلم، فالصحيح: أنه لا حرج في ذلك، وقد ثبت عنه ﷺ أن جماعة من الصحابة جاءهم بعض العرب وأخبرهم أن سيدهم يعني: رئيسهم لديغ وأنهم فعلوا كل شيء لا ينفعه، وطلبوا منهم أن يرقوه فتقدم أحد الصحابة ورقاه بفاتحة الكتاب، فشفاه الله وعافاه وكانوا اشترطوا عليهم قطيعاً من الغنم، فأوفوا لهم بشرطهم، فتوقفوا عن قسمه بينهم حتى سألوا النبي ﷺ فقال: أحسنتم واضربوا لي معكم بسهمم  ولم ينكر عليهم ذلك، وقال: إن أحق ما أخذتم عليه أجراً كتاب الله رواه البخاري في الصحيح.\nفهذا يدل على أنه لا بأس بأخذ الأجرة على التعليم إذا كان التطبب وقراءة الفاتحة ونحوها على اللديغ والمريض لا بأس أن يؤخذ عنه أجرة، فالتعليم أنفع للناس وأكثر حاجة، فلا بأس أن يؤخذ عنه الأجرة في تعليم العلم تعليم القرآن وتحفيظه ولا حرج في هذا والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6463/حكم-اخذ-الاجرة-على-تحفيظ-الصبيان-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12304.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8494,"question":"هنا رسالة بعثها أحد الإخوة من مكة المكرمة -الزاهر- يقول فضل محمد أحمد السوداني أخونا يسأل ويقول: لي أرض بالسودان أرض زراعية ولم أستطع إصلاحها، ففكرت في إيجارها لمن يستطيع إصلاحها وعندما شرعت في ذلك بلغني من أحد الفقهاء هناك بأن إيجار الأرض لا يجوز، يجوز أن تعطيها بجزء من المحصول ولا يجوز إيجارها فهل هذا صحيح؟","title":"حكم إيجار الأرض","answer":"الجواب: ليس هذا بصحيح يجوز تأجير الأرض بشيء معلوم كالدراهم والأصواع المعلومة كما قال رافع بن خديج عن النبي ﷺ أنه قال: فأما شيء معلوم مضمون فلا بأس به فتأجير الأرض بشيء معلوم من دراهم أو دنانير أو أصوع معلومة من جنس ما يخرج منها أو غيره لا بأس بذلك، هذا هو الذي عليه أهل العلم وهو الحق وإن كان بعض الناس قد خالف في ذلك لكن خلاف لا وجه له، والصواب أنه يجوز تأجيرها بجزء مشاع مما يخرج منها كالربع والثلث ونحو ذلك، ويجوز تأجيرها بشيء مضمون معلوم كمائة درهم ألف درهم ألف صاع ألف كيلو من الحنطة من الأرز من الشعير كل هذا لا بأس به.\nأما الذي ينهى عنه فهو أن يؤجرها ببقعة منها، فيقول: لك ما نبت هنا ولي ما نبت هنا، فهذا يفضي إلى الغرر فقد تنبت هذه ولا تنبت هذه، قد تكون هذه أطيب من هذه فإذا أجره الأرض على أن له ما نبت في الجناح الشمالي أو في الجناح الغربي أو الجنوبي أو نحو ذلك هذا ليس بصحيح، أو قال لك أو لي ما نبت على السواقي -على الجداول مثلاً- وأما ما سوى ذلك فللآخر فهذا كذلك لا يصلح، وقد نص على ذلك في رواية رافع بن خديج ، عن النبي ﷺ وهذا يكون فيه جهالة، وإنما يجوز تأجيرها بشيء معلوم مضمون من آصع أو دراهم أو دنانير أو نحو ذلك، أو بجزء مشاع معلوم كالربع والثلث والنصف ونحو ذلك، هذا هو الذي يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/6554/حكم-ايجار-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12608.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8758,"question":"يقول: إنه يعمل خادم في مسجد ويستلم ألف وخمسين ريال، وهو لا يعمل في المسجد إلا أنه يعطي أحد الإخوة الباكستانيين مبلغ أربعمائة ريال؛ لينظف المسجد فما الحكم؟","title":"حكم من أوكل إليه عمل براتب واستأجر غيره ليقوم به","answer":"الجواب: لا بد من مراجعة الأوقاف، ومشاورة الأوقاف إذا سمحت لك الأوقاف بذلك فلا بأس، وإلا فالواجب عليك أن تباشر العمل وأن تتقي الله في ذلك حتى تستحل الأجرة؛ لأن الباكستاني قد لا يقوم بعملك وقد لا يحصل به المقصود، ولأن التساهل في هذا يفضي إلى شر كبير، من تعطيل المساجد وعدم تنظيفها وعدم العناية بها، أو تولية إنسان لا يصلح لسوء كلامه أو لسوء أعماله أو لعدم استقامته مع الإمام ومع أهل المسجد، فالحاصل أن هذا شيء فيه خطر فالواجب عليك أن تستشير مرجعك فإذا سمحوا لك بأن تستنيب فلان أو فلان بأجرة أو بغير أجرة فلا بأس.\nالمقدم: بارك الله فيكم وجزاكم الله خير!","link":"https://binbaz.org.sa/fatwas/6918/حكم-من-اوكل-اليه-عمل-براتب-واستاجر-غيره-ليقوم-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21713.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":9444,"question":"يقول أيضاً في هذه الرسالة: أنا مستأجر لدكان، وقد اتفق معي رجل على أن أترك له الدكان مقابل خمسة آلاف جنيه برضا المالك، والذي زاده هذا المستأجر الجديد في الإيجار من مائة جنيه إلى مائة وخمسين شهرياً، فهل يجوز لي أن آخذ منه هذا المبلغ وهو يسمى عندنا: خلو رجل، أفيدونا أفادكم الله؟","title":"حكم اتفاق المستأجر الجديد مع القديم على ترك الدكان مقابل مبلغ","answer":"الجواب: هذا المبلغ لا أصل له ولا وجه له، ما دام المدة تمت فليس لك أخذها إلا إذا كانت هبة من المالك وسماحًا منه، أما أن تأخذها باسم أنها حق لك أو أنك يعني لا يمكن أن تدع الدكان إلا بهذا المبلغ، لا. لأنه لا حق لك فيه، إنما حقك في الدكان إذا بقيت المدة، فالمدة الباقية لك تؤجرها بما تشاء، أما بعد فراغ المدة فليس لك حق أن تأخذ شيئًا، وإنما التصرف لصاحب الملك هو الذي يتصرف يؤجره عليك أو على غيرك، ولو كانت الدولة جعلت هذا لك فالدولة لا تحل الحرام والناس أولى بأملاكهم، أصلح الله الجميع.\nالمقدم: بارك الله فيكم، يعني هذا المبلغ سماحة الشيخ لا يؤخذ من المالك؟\nالشيخ: لا يأخذه من المالك ولا من المستأجر.\nالمقدم: الجديد؟\nالشيخ: من الجديد، إذا كانت المدة قد تمت. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7612/حكم-اتفاق-المستاجر-الجديد-مع-القديم-على-ترك-الدكان-مقابل-مبلغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25505.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":9682,"question":"أخيراً يسأل عن إذا جاء الإنسان بشخص إلى بيته ليقرأ له القرآن، ويجزيه بعد ذلك بمبلغ من المال ما حكم ذلك، أفيدونا أفادكم الله؟","title":"حكم أخذ الأجرة على مجرد التلاوة للقرآن","answer":"الجواب: أخذ الأجرة على التلاوة أمر لا يجوز، وقد حكى بعض أهل العلم إجماع أهل العلم على ذلك، لا يجوز أن يقرأ الإنسان بالأجرة بمجرد التلاوة حتى يعطى أجرة في بيت فلان، أو بيت فلان، أو على مريض فلان، لا، يقرأ احتساباً ولا يعطى أجرة، أما إن أهدي هدية، أو أعطي شيئاً من دون مشارطة فنرجو أن لا يكون عليه شيء في ذلك من باب الإحسان إذا كان فقيراً، يعطى من باب الإحسان، أما أن يكون مشارطة يكون اليوم بكذا، أو كل جزء بكذا، أو السورة بكذا، هذا منكر لا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7848/حكم-اخذ-الاجرة-على-مجرد-التلاوة-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25207.mp3","categories":["الإجارة","القرآن وعلومه"]},{"id":9699,"question":"تقول هذه الأخت السائلة من اليمن أيضاً: لي ابن موظف عند صاحب مال، وليس له راتب شهري معين؛ لأنه كلما احتاج شيء من المال أعطاه إياه، ولو قدرنا الذي عند التاجر لوجدناه حوالي مائة ألف ريال، لكنها عند صاحب المال يعتبرها جزء من ماله يتاجر بها، يعني: لا يعطي لابنها مالاً إنما ما له من حق يجعله ضمن ماله أي التاجر، وعند إخراج الزكاة قال ابني للتاجر: كم لي عندك حتى أدفع زكاة مالي، قال التاجر: أنا الذي سأزكي مالك مع مالي؟","title":"حكم التوظف دون تحديد الراتب","answer":"الجواب: هذا العامل يجب أن يعين له راتب معين، وليس له أن يعمل هكذا من دون راتب معين؛ لأن هذا يفضي إلى النزاع والخصومة، ولأنه راتب مجهول وأجر مجهول فلا يجوز، فالواجب أنه يعين له راتب معين يصطلحان عليه، وبعد ذلك هو الذي يزكيه كلما حال عليه الحول زكاه صاحبه العامل، وإذا اصطلحا عما مضى بشيء معلوم فإنه يزكيه العامل بعد أن يحول عليه الحول. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7894/حكم-التوظف-دون-تحديد-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25403.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":9795,"question":"لها استفسار ثالث تقول فيه: في أيام الأعراس والأفراح يجتمع النساء ويعطون من يسمون بالدفافات نقودًا من أجل الرقص، هل هذا حرام أم لا؟","title":"حكم إعطاء النقود لمن يضربن على الدف","answer":"الجواب: لا حرج في هذا إن شاء الله لكن يكون قليل، ينبغي أن يكون قليلًا ليس فيه مباهاة ولا إسراف فلا حرج فيه؛ لأن هذا جرت به العادة والشعراء يعطون لكن ينبغي أن يكون قليلًا. نعم.","link":"https://binbaz.org.sa/fatwas/7962/حكم-اعطاء-النقود-لمن-يضربن-على-الدف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19611.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10026,"question":"تقول أني أخيط الملابس النسائية والأقمشة المختلفة منها الشفاف الخفيف ومنها غير ذلك، والنساء التي يأتينني آراؤهن مختلفة في لبس الملابس، منهن من يلبس القصير ومنهن غير ذلك، وإنني أنصحهن على ذلك ومنهن من يستمع ومنهن من يصر، وإني أخاف أن يكون كسبي من خياطة هذه الملابس للناس الذين لا يخافون الله حرامًا، أرشدوني جزاكم الله خيرًا؟","title":"حكم خياطة الملابس النسائية التي ليست ساترة","answer":"الجواب: الذي يصر على لبس القصير لا تخيطين له شيء لا تعينه على المعصية والذي يقبل النصيحة ويقول: إنه يمتثل فلا مانع، والشفاف يبين لهن أن الشفاف لا يجوز لبسه وحده، لكن إذا كانت تلبسه فوق الساتر فلا بأس، فعليك أن تعينيهن على الخير وأن تنصحيهن وأن تمنعيهن من الشر، ولو بالكلام والنصيحة والذي لا يمتثل وتعلمين أنه يلبس القصير أو الشفاف الذي لا يستر وحده دون أن يكون تحته ساتر لا تعينينه على ذلك لا تعينيه ولا تخيطي له لأن الله يقول سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فالواجب على المسلمين التعاون على البر والتقوى وأن لا يتعاونوا على الإثم والعدوان، فكل امرأة تعرفين عنها لبس القصير فلا تخيطين لها القصير، وكل امرأة تعرفين عنها أنه تلبس الشفاف وليس تحته ساتر لا تعينيها على ذلك وانصحيها وعلميها وامتنعي من مساعدتها وأبشري بالخير، سوف يعوضك الله خيرًا منهن وسوف يأتي الله لك برزق طيب تعويضًا لك عما فعلت من الخير، لأنه سبحانه يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3].\nويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فعليك أن تتقي الله وأن لا تساعدي النساء اللاتي يتعمدن المعصية لا في اللباس ولا في غيره. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8194/حكم-خياطة-الملابس-النساىية-التي-ليست-ساترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33206.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10118,"question":"المستمع (س. ع) بعث يسأل ويقول: هل لي أن أستلم مكافأة مقدارها ثلاثمائة ريال شهريًا مقابل كفالة أحد العمال ليبقى عاملًا في المملكة عند غيري؟","title":"حكم استقدام العمال وأخذ مبلغ شهري مقابل الكفالة","answer":"الجواب: ليس لك ذلك، وإنما تستقدمه بأجرة معلومة شهرية حتى يعمل عندك أو عند غيرك ممن اتفقت معهم بأجر معلوم تعطيه إياه كل شهر، وأما أن يعطيك دراهم عن كفالته فلا. وقد نظر مجلس هيئة كبار العلماء في ذلك وقرر أنه لا يجوز استقدامهم إلا على الطريقة التي رسمتها الدولة، الطريقة التي قررتها الدولة وأقرتها ولا يجوز استقدامهم على الطرق الأخرى لما في ذلك من الفساد والشر على الناس، فإذا أراد عاملًا يستقدمه على الطريقة التي رسمتها الدولة وبينتها الدولة وهو أن يستقدمه بأجر معلوم شهري أو يومي أو سنوي على أنه يعمل كذا بمزرعته في بناء في كذا..في عمل معلوم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8288/حكم-استقدام-العمال-واخذ-مبلغ-شهري-مقابل-الكفالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33406.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10524,"question":"يقول في سؤال آخر: علمنا أنه يحرم البيع بعد النداء الثاني في يوم الجمعة، فهل هذا ينطبق على أصحاب سيارات الأجرة والباصات الذين يتقاضون على إركاب الركاب قيمة معينة وجهونا؟ وهل من توجيه لهم، جزاكم الله خيراً؟","title":"حكم تقاضي أجرة السيارات بعد النداء الثاني للجمعة","answer":"الجواب: نعم، تأجير السيارات بيع؛ لأن الأجرة بيع، بيع المنافع، يدخل في الآية الكريمة: إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ  [الجمعة:9] تقف السيارات، ويقف أهل التكاسي ويتوجهون إلى المسجد يجب عليهم، ولا يجوز لهم أن يؤجروها في هذه الحال، بل يوقفونها ويتوجهون إلى المسجد إذا سمعوا النداء هذا هو الواجب عليهم؛ لأن التأجير نوع من البيع، بيع المنافع يسمى: أجرة، وهو بيع. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ! إذا كان النداء الثاني يتفاوت من مسجد إلى آخر، قد يكون بين بعض المساجد والبعض الآخر ما يقرب من نصف ساعة، ما هو توجيه سماحة الشيخ؟\nالشيخ: متى سمع المنادي في المحل الذي فيه كفى.\nالمقدم: إذًا العبرة بالمحل...؟\nالشيخ: بالمحل الذي هو فيه. نعم.\nالمقدم: بارك الله فيكم، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8699/حكم-تقاضي-اجرة-السيارات-بعد-النداء-الثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28313.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":10544,"question":"هذا سائل أرسل بهذا السؤال لم يذكر الاسم في هذه الرسالة يقول سماحة الشيخ: أنا أعرف صاحب مؤسسة لديه الكثير من العمال قد يصل عددهم إلى خمسة عشر عامل، وهو لا يقوم بصرف المرتب لهم، مع العلم بأنه لم يصرف لهم المرتب منذ سبعة أشهر، وكذلك لا يعطيهم الإعاشة كاملة، وهم في حالة يرثى لها، فنرجو من سماحة الشيخ النصح لمثل هذا؟","title":"حكم من يستقدم عمالاً ولا يعطيهم حقوقهم أو يأخذ أموالاً لكفالتهم","answer":"الجواب: الواجب على المسلمين العناية بالعمال وإعطاؤهم حقوقهم وإعاشتهم ولا يجوز لهم التساهل في هذا، هذا منكر وظلم، بل يجب على صاحب العمال الذين استأجرهم أن يعطيهم حقوقهم حسب الشروط، إن كانت تقدم كل شهر وجب تقديمها كل شهر، وإن كان بينه وبينهم على شهرين شهرين وهكذا على الشروط اللي بينهم، مع الإعاشة المشروطة لا يخل بها، هذا هو الواجب: والظلم ظلمات يوم القيامة : كل المسلم على المسلم حرام دمه وماله وعرضه وفي الحديث الصحيح يقول النبي ﷺ: يقول الله جل وعلا: ثلاثة أنا خصمهم يوم القيامة: رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا فاستوفى منه ولم يعطه أجره هذا من المنكرات العظيمة.\nفالواجب الحذر وألا يكلفهم ما لا يطيقون، وألا يؤجل حقوقهم، بل يجب أن يعطيهم حقوقهم حسب الشروط، نعم.\nالمقدم: سماحة الشيخ! أولئك الذين يأتون بالعمال ويأخذون منهم مبالغ مالية كل شهر ويتركونهم يسرحون ويمرحون، ما حكم هذه النقود التي يأخذونها، الذي يأخذها الكفيل وغيره؟\nالشيخ: لا يجوز هذا العمل، وقد صدر قرار من هيئة كبار العلماء بمنع هذا، وأن الواجب استقدامهم على الطريقة التي رسمتها الدولة، أما أن يستقدمهم ..... يجعلهم بين الناس يعملون، ويأخذ منهم كل شهر كذا وكذا من أجل كفالته فهذا لا يجوز، الواجب على المؤمن أن يستقدم حاجته فقط هو، على حسب الشروط التي نظرتها الدولة.","link":"https://binbaz.org.sa/fatwas/8719/حكم-من-يستقدم-عمالا-ولا-يعطيهم-حقوقهم-او-ياخذ-اموالا-لكفالتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28416.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11119,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل عن صيد الأسماك فيقول: هل يجوز لي أن أستخدم العمال في صيد الأسماك بدون راتب، علمًا بأني أعطيهم نصف الإنتاج، وآخذ النصف الآخر؟ وأحيانًا في اليوم كله لا نصيد شيئًا، ولا توجد بيننا أي شروط بين العمال، وصاحب المراكب الشراعية، جزاكم الله خيرًا.","title":"حكم استئجار عمال للصيد على نصف ما يصيدونه","answer":"الجواب:  إذا اتفقوا على ذلك فلا بأس، لا حرج، هذا صلح بينهم، واشتراك بينهم لا حرج فيه، إذا اشتركوا للصيد أنصافًا، أو أرباعًا فلا حرج، سواءً صيد البر، أو صيد البحر، تراضوا على هذا فلا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9287/حكم-استىجار-عمال-للصيد-على-نصف-ما-يصيدونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36805.mp3","categories":["الإجارة"]},{"id":11391,"question":"من المدينة المنورة رسالة بتوقيع إحدى الأخوات المستمعات تقول: المرسلة (ف. ع) أختنا تقول: لدي مؤسسة باسمي، لكن زوجي يتولى الأعمال، وقد استخرجنا عشرين فيزة، وبعد ذلك طلب من العمال مبلغ ثلاثمائة ريال شهرياً، ويعملوا على حسابهم الخاص، وأنا محتارة في ذلك، فهل ما قام به زوجي جائز أم لا؟ علمًا بأن زوجي يصر على أن ذلك جائز بعد أن ناقشته أكثر من مرة، أفيدوني جزاكم الله خيرًا.","title":"حكم أخذ مبالغ مالية ممن يتم استقدامهم للعمل","answer":"الجواب:  عليك وعليه السير على ما رسمت الدولة في استقدام العمال، وعدم الخروج عن ذلك، عليكما العمل بالتعليمات التي رسمتها الدولة فيما يتعلق بالعمال، وليس لكما الخروج عن ذلك؛ لأن عليكما السمع والطاعة في المعروف وهذا من المعروف. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9557/حكم-اخذ-مبالغ-مالية-ممن-يتم-استقدامهم-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37906.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11406,"question":"رسالة بعث بها مستمع يقول: (أ. س. د) يقول: أعمل مهندسًا في مؤسسة في إحدى مناطق المملكة، وتعاقدت مع كفيلي، واتفق معي على اتفاقات مادية ومعنوية، ولكنه بعد مضي سنة أخلف بعض الاتفاقات المادية والمعنوية، أفتوني ماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم من عقد مع كفيله اتفاقات ولم يف الكفيل بها","answer":"الجواب: عليك أن ترفع أمره إلى المحكمة، تطلب الشرع إلا إذا اصطلحت أنت وإياه، أو أصلح بينكما بعض الإخوان؛ طيب، الصلح خير، فإذا تيسر من يصلح بينكما بأن تسمح عن بعض حقك، أو يؤدي الحق كله هو. فالمقصود: الصلح طيب إذا تيسر، فإن لم يتيسر الصلح وأبى؛ فليس لك إلا المحكمة، ترفع أمرك إلى المحكمة، وفيما تراه المحكمة الكفاية، إن شاء الله. المقدم: بارك الله فيكم.  الشيخ: إذا كنت في بلاد تحكم بالشرع، إذا كنت في بلاد تحكم بالشرع. المقدم: يقول: إنه في إحدى مناطق المملكة، جزاكم الله خيرًا. الشيخ: ........ المحكمة والحمد لله، نعم. المقدم: الحمد لله، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9586/حكم-من-عقد-مع-كفيله-اتفاقات-ولم-يف-الكفيل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38006.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11554,"question":"يقول: أنا أعمل في محل بيع لملابس النساء، فبماذا تنصحونني؟ جزاكم الله خيرًا، ولا بد أنه وصلكم طريقة النساء في الأسواق؟","title":"حكم العمل في محلات بيع ملابس النساء","answer":"الجواب:  أنت أعلم بنفسك، إذا كان عملك هذا قد يجرك إلى شر وفتنة بالنساء؛ فاترك العمل، والتمس عملًا آخر، أما إذا كان لا يضرك، بل تستعمل طريقًا لا يضرك معه هذا العمل، ويمكن البيع والشراء من دون فتنة؛ فلا حرج عليك في ذلك، أنت أعلم بنفسك، وأنت أدرى بالواقع. والذي أنصحك به أن يكون عملك غير هذا العمل؛ لأن .... النساء في الغالب تجر إلى فتنة، ولاسيما قد يخلو بالواحدة منهن لتفتيش الملابس، والنظر في الملابس، فتكون الفتنة أكبر وأعظم، فالتماس عملًا آخر ليس فيه فتنة خير لك، وأولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9737/حكم-العمل-في-محلات-بيع-ملابس-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29703.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11646,"question":"يقول: إذا كان الإنسان لديه والدته، وهي كبيرة، ولكنها تقدر والحمد لله على المشي مع أنها تتعبها مشاغل المنزل، وليس عندها من يساعدها، هل يجوز لي استقدام خادمة للقيام بأعمال البيت، وخدمة والدتي، وجهونا حول هذا الموضوع حيث أن بعض الناس استقدم منهن، ولكن بعض الناس أنكر عليه ذلك، وجهوا لنا هذا الموضوع جزاكم الله خيرًا.","title":"حكم استقدام خادمة للضرورة","answer":"الجواب:  لا حرج في ذلك، استقدام خادمة من المسلمين ما هو من الكفار، خادمة مسلمة لا يجوز استقدام الكفرة إلى هذه الجزيرة العربية، ولكن استقدام مسلمة حتى في غير الجزيرة، الأحوط للمؤمن ألا يستقدم إلا مسلمة، لكن في الجزيرة لا يجوز استقدام الكفرة؛ لأن الرسول أمر بإخراجهم من هذه الجزيرة -عليه الصلاة والسلام- وليس لك أن تخلو بها، تكون مع الوالدة، تبيت معها وتعاونها، وليس لك أن تخلو بها، وعليك غض البصر، والحذر من أسباب الشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9828/حكم-استقدام-خادمة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38915.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11917,"question":"يقول: نلاحظ كثيرًا من الناس يعيشون على الدلالة، وكلما يفعله هؤلاء الدلالون هو أن يوفق بين البائع والمشتري على أن تكون عمولة للدلال كذا وكذا في المائة، فهل تجوز هذه المهنة؟ مع العلم بأن كثيرًا من الدلالين يحلفون للبائع، أو المشتري بالكذب حتى يوافق على تمام البيع، وبعض الدلالين يخفون العيب الذي يكون في الشيء المباع على المشتري؛ لكي يتم البيع وجهونا جزاكم الله خيرًا.","title":"حكم مهنة الدلالة وأخذ الأجرة عليها","answer":"الجواب:  الدلالة لا بأس بها كونه يأخذ نصيبًا، يبيع أرض فلان، بيت فلان، سيارة فلان، ويأخذ أجرة؛ لا بأس، لكن لا يجوز له أن يكذب، ولا أن يغش البائع، ولا أن يغش المشتري، حرام عليه ينصح لهؤلاء ولهؤلاء، ولا يكتم العيب، ولا يكذب على صاحب السلعة، ويقول: إنها هذا حدُّها، وهو يكذب لأجل مصلحة المشتري. المقصود أن عليه النصح، والحذر من الكذب، وإخفاء العيوب، وإذا فعل شيئًا من هذا؛ فقد أثم، وصار كسبه خبيثًا، لكن عليه أن يتقي الله، وأن ينصح لهذا وهذا، للبائع والمشتري، ويبرئ ذمته، ولا يجوز له كتمان العيوب، ولا الغش، ولا الخيانة، ولا الكذب لا على المشتري، ولا على البائع، هذا الواجب عليه أن ينصح لله، ولعباد الله، وبذلك تكون مهنته لا بأس بها، ويكون أجره لا بأس به، أما إن كان غش الناس، وخان الأمانة، وكذب؛ فقد تعاطى منكرًا عظيمًا، نسأل الله العافية، وصارت دلالته فيها الشر الكثير، ولم تجز له حلالًا؛ بسبب غشه وخيانته وكذبه، نسأل الله العافية. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10101/حكم-مهنة-الدلالة-واخذ-الاجرة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42618.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":12051,"question":"بعد هذا ننتقل إلى الجمهورية العربية السورية عبر رسالة بعث بها مستمع يقول: محمد حلمي، أخونا يقول: إن زوجتي تعمل حلاقة للسيدات من قص للشعر، وتزيين، وصباغ وغير ذلك، وأنا بحاجة لهذا العمل، وهي كذلك؛ لأننا في حاجة إلى شيء من المال، فهل هذا العمل حلال، أم حرام؟","title":"حكم عمل المرأة في مجال حلاقة وتصفيف شعر النساء","answer":"الجواب:  لا نعلم فيه بأسًا، إذا كان المأخوذ جائزًا، إذا مشطتهن، وشدت رؤوسهن، وأخذت الشيء الزائد، الذي ترى المراة أخذه من أطراف عمائلها للتحسين، لا حرج في ذلك، ولكن لا يجوز أن تأخذ شيئًا من المرأة إلا بإذن الزوج إذا كان شيئًا له أهمية، فالمرأة ليس لها أن تأخذ من شعرها إلا وزوجها عالم، إلا إذا كان الشيء الخفيف اليسير الذي دعت الحاجة إلى أخذه، والغالب أن مثله لا يمنعه الزوج، كالأطراف اليسيرة، وما أشبه ذلك؛ فلا حرج في ذلك، فهكذا مشطهن ..... المشط يكون معتادًا الذي ليس فيه تشبه بالكافرات، لم يزلن الماشطات يمشطن للنساء في عهد النبي -عليه الصلاة والسلام- فالماشطة التي تعدل الرأس، وتحسنه؛ لا حرج فيه، لا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/10236/حكم-عمل-المراة-في-مجال-حلاقة-وتصفيف-شعر-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43320.mp3","categories":["قضايا المرأة","الإجارة"]},{"id":13027,"question":"السؤال الأخير يقول: لقد أحضرت خمسة عمال، وأخذت من كل واحد منهم مبلغًا من المال لقاء أتعابي، فهل المال الذي أخذته حلال، أم حرام؟","title":"حكم أخذ الإنسان مالًا من عامل استقدمه للعمل","answer":"الجواب:  إذا كان شيء مقابل ما أنفقته في تحصيل ما ينفعهم، أما إحضارهم لتأخذ مالًا منهم؛ فلا يصح، لا يجوز هذا. لكن إذا أحضرتهم، وأحسنت إليهم، وسعيت في طلب الإقامة لهم، وهم طيبون أخيار؛ فلا بأس، وليس لك أن تأخذ إلا بقدر ما صرفت عليهم في طعامهم، وشرابهم، أو في شراء حاجات لهم، أو غير هذا مما تصرفه في حاجاتهم، نعم.  المقدم: جزاكم الله خيرًا، الواقع سماحة الشيخ هناك ما يسمى بالاتجار بالعمال توجيهكم؟ الشيخ: هذا غلط، الاتجار بالعمال لا يجوز، وقد صدر قرار من هيئة كبار العلماء بمنع ذلك، وأن الواجب ألا يستقدموا إلا على الطريقة التي أوضحتها الدولة، وبينتها الدولة، فمن أراد أن يستقدم؛ فعليه أن يسلك الطرق التي رسمتها الدولة، نعم، حتى لا يضر نفسه، ولا يضر المسلمين.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11244/حكم-اخذ-الانسان-مالا-من-عامل-استقدمه-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47207.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":13276,"question":"هذا السائل -سماحة الشيخ- سلامة مسعد مصري، ويعمل بالأردن، يقول: أرجو معرفة وإدراك العائد من مهنة الحلاقة الرجالي من أموال، هل هذا العائد من المال حرام؟ نرجو بهذا إفادة.","title":"حكم أجرة الحلاقين من حلق اللحى","answer":"الجواب:  هذا فيه تفصيل: إذا كانت الحلاقة للرأس؛ فلا بأس، والعائد منها حلال طيب، لا بأس. أما إن كان الحلاق يحلق لحى الناس؛ فهذا منكر، والعائد منها خبيث لا يجوز. فالواجب على الحلاقين أن يتقوا الله، وألا يحلقوا اللحى، ولا يقصوها، ومن قال لهم يأبون وينصحونه، يقولون له: ما يجوز، الرسول ﷺ قال: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وقال -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وقال -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس. فالحلاق لا يحلق اللحى، ولا يقصها، وينصح من يطلب ذلك، ويمتنع من موافقته، والكسب الذي يأتي من طريق حلق اللحى خبيث، ومحرم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11561/حكم-اجرة-الحلاقين-من-حلق-اللحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51409.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":13482,"question":"يقول: لدينا عندما يتوفى أحدنا يقوم أهل الميت بدعوة بعض أئمة المساجد، أو ما يسمى عندنا بالشيوخ، وهم مجموعة لا يقل عددهم عن عشرة، يقومون بتلاوة القرآن ترحمًا على الميت، ولكن يكون هذا المقابل من أهل الميت، يقوم واحد من أهل الميت بتوزيع بعض النقود عليهم جميعًا بعد الانتهاء من ختمة القرآن، فما حكم الإسلام في هذا؟","title":"حكم أخذ الأجرة على قراءة القرآن وتثويب القراءة للميت","answer":"الجواب: هذا غير مشروع، ولا يجوز أخذ الأجرة على تلاوة القرآن، ولا تثويبها للموتى، هذا غير مشروع، وما كان الصحابة يفعلون هذا  أما كونه يقرأ بين الحاضرين إذا اجتمعوا ليستفيدوا من كلام الله  من دون أجرة، لو اجتمع الناس في مجلس يعزون، أو في زيارة، أو في وليمة، وقرأ واحد ليسمعهم القرآن، ويستفيدوا هذا شيء طيب، كان النبي ﷺ في مجالسه يقرأ القرآن، ويستمعون، ويشرح لهم ﷺ ويبين لهم، وربما أمر بعض الصحابة أن يقرأ وهو يستمع، عليه الصلاة والسلام. أما إحضارهم من أجل القراءة للتثويب للميت، وأن يعطوا على هذا أجرة؛ فهذا منكر لا يجوز، وليس من الإسلام، بل هذا بدعة، وقد أجمع العلماء على أنه لا يجوز للمسلم أن يأخذ الأجرة على تلاوة القرآن، إنما يأخذ على التعليم، على تعليم الناس القرآن، الصحيح يجوز أن يعطى أجره على التعليم حتى يتفرغ للتعليم، أما مجرد التلاوة يأتي يتلو ثمنًا، أو ثمنين، أو جزءًا، أو جزأين؛ ليأخذ فلوسًا؛ هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11785/حكم-اخذ-الاجرة-على-قراءة-القران-وتثويب-القراءة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47811.mp3","categories":["البدع والمحدثات","الإجارة"]},{"id":13645,"question":"في آخر أسئلة هذا السائل من جمهورية مصر العربية يقول: ما حكم الإكرامية، وهي أن يعطي الرجل الأجير أكثر من أجره طواعية منه؟","title":"حكم إعطاء الأجير زيادة على أجرته","answer":"الجواب: هذا يشكر عليه، إذا أعطاه فوق حاجته؛ لأنه ناصح، ولأنه مجتهد، يقول النبي ﷺ: إن خيار الناس أحسنهم قضاء فإذا كان الأجير جيد، وناصح، وزاده في الأجرة؛ فهذا من مكارم الأخلاق. نعم . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11977/حكم-اعطاء-الاجير-زيادة-على-اجرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52816.mp3","categories":["الإجارة"]},{"id":14503,"question":"أولى رسائل هذه الحلقة رسالة المستمع حسني محمد عبدالرحيم، الأخ حسني يقيم الآن في جزيرة قبرص، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول:إنني وحيد في جزيرة قبرص، ولم أجد مسلمين أصلي معهم، ولا يوجد أي مسجد، إلا أنني أسمع الأذان عن طريق إحدى الدول العربية بالراديو، وأصلي الجمعة خلف المذياع في إحدى الدول العربية، فهل صلاتي هذه تعتبر صلاة جماعة؟ وماذا أفعل -إذًا- وأنا أتأخر في بعض أوقات الصلاة؛ لأنه لا بد لي من الاغتسال خوفًا أن يكون عملي -الذي سبق وأن ذكرته لكم وهو في مصنع للحوم الخنازير- أخشى أن يكون في عملي هذا شيء من النجاسة، فأغتسل قبل الصلاة، أرجو توجيهي حيال ما سألت، جزاكم الله خيرًا.","title":"حكم صلاة الجمعة خلف المذياع والعمل في مصنع لحوم الخنازير","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أنّ صلاة الجمعة واجبة على المسلمين، ولكن ليس لك أن تصلي على المذياع، بل الواجب عليك أن تلتمس من المسلمين من يقيم الصلاة صلاة الجمعة، وعليك أن تجتهد في ذلك، فإذا تيسر لك جماعة من المسلمين في أي مسجد من المساجد تصلي معهم الجمعة، ولو اثنين، وتكون أنت الثالث؛ لأن الصحيح أنّ الجمعة تنعقد من ثلاثة، فإذا كانوا مستوطنين مقيمين في بلد ليسوا مسافرين بل مقيمون مستوطنون، فإنكم تصلون جميعًا جمعة، وإذا كانوا أكثر من ثلاثة فأحسن وأحسن.\nوينبغي لك وأمثالك من الإخوان الطيبين أن يسعوا في هذا الأمر، وأن يجتهدوا في إقامة صلاة الجمعة، وصلاة الجماعة في المساجد الموجودة، وأن تحرصوا على فتحها؛ لأنه بلغني أنّ هناك مساجد كثيرة مغلقة، فينبغي لك أنت وإخوانك أن تسعوا حثيثًا في فتح ما تيسر منها، وأن تقيموا صلاة الجمعة فيما تيسر منها، ولا تصل خلف مذياع، لكن إذا لم يتيسر لك أحد تصلي ظهرًا، صل أربعًا ظهرًا بعد زوال الشمس، بعد دخول الوقت، ولا تصل جمعة إلا إذا كان معك اثنان أو أكثر من الناس المستوطنين في البلد، هكذا بيّن أهل العلم.\nونسأل الله أن يجعلك مباركًا، وأن يعينك على أسباب الخير، وأن يجعلك مفتاحًا للخير. أما الغسل فهو سنة سنة مؤكدة يوم الجمعة لمن يصلي الجمعة، وذهب بعض أهل العلم إلى وجوبه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من جاء منكم الجمعة فليغتسل وقال أيضًا -عليه الصلاة والسلام-: غسل يوم الجمعة واجب على كل محتلم، وأن يستاك ويتطيب. قال جمهور أهل العلم: معنى واجب يعني: متأكد، فيسن لك الغسل للجمعة إذا كنت تصلي الجمعة. أما صلاة الأوقات فلا يشرع لها الغسل، وإذا كنت تعلم أن في ثوبك نجاسة، أو بدنك نجاسة من لحم الخنزير، أو دم الخنزير، أو من بول أو غير ذلك فاغسله، اغسل المحل فقط، وليس عليك غسل، عليك أن تغسل ما أصابه الدم أو النجاسة من الخنزير في يدك أو رجلك أو ثوبك، أما الغسل فلا يلزمك، لكن يستحب لك الغسل في الجمعة. ويجب عليك الغسل للجنابة إذا جامعت زوجتك، أو أنزلت مني بشهوة تغتسل للجنابة، نسأل الله أن يعينك على الخير، وأن يمنحنا وإياك الفقه في الدين، والثبات عليه، ونوصيك مرة أخرى بالحرص على جمع إخوانك، والتعاون معهم، وأن تصلوا جميعًا الجمعة والجماعة، وأن تجتهدوا في فتح المساجد تشجيع من حولها من المسلمين يصلوا فيها الجمعة والجماعة، كل مسجد حوله جماعة يصلوا فيه الجماعة، وإذا كانت الجمعة بعيدة عنهم صلوا جمعة أيضًا، وإذا كانوا متقاربين اجتمعوا في واحد من المساجد وصلوا جمعة، ولا يتفرقوا، بل يصلون جميعًا في مسجد واحد، إلا إذا تباعدت المساجد والمحلات تباعدًا كثيرًا، فكل حي يصلون في حيهم جمعة إذا صار بعيدًا عن الحي الآخر بما يشق معهم الذهاب إلى الحي الآخر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nسماحة الشيخ، بم توصونه تجاه عمله في هذا المصنع، مصنع للحوم الخنزير؟\nالشيخ: تقدم أن أوصيناه بأنه يجب عليه تركه، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ليس له أن يعمل في مصنع الخنزير، وليس لأحد أن يساعد صناع ما حرم الله من صناعة الخمر، أو بيع لحم الخنزير، أو غير هذا مما حرم الله، ليس للمسلم أن يشاركهم في ذلك، ولا أن يعينهم في ذلك؛ لأن الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] والنبي ﷺ لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها، والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها؛ لماذا؟ لأنهم ساعدوا على الباطل؛ لأنهم عاونوا على الشر، فلهذا لعنوا.\nفالواجب على كل مسلم وعلى كل مسلمة الحذر من الإعانة على ما حرم الله، عملًا بقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة:2] فالذي يعين على بيع الخمر، أو بيع الخنزير، أو أكل لحم الخنزير، أو شرب المسكر، أو يعين على أكل الربا، أو يكتب الربا، أو يشهد على الربا كلهم داخلون في اللعنة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12993/حكم-صلاة-الجمعة-خلف-المذياع-والعمل-في-مصنع-لحوم-الخنازير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62601.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":14510,"question":"أولى رسائل هذه الحلقة رسالة المستمع حسني محمد عبدالرحيم، الأخ حسني يقيم الآن في جزيرة قبرص، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول:إنني وحيد في جزيرة قبرص، ولم أجد مسلمين أصلي معهم، ولا يوجد أي مسجد، إلا أنني أسمع الأذان عن طريق إحدى الدول العربية بالراديو، وأصلي الجمعة خلف المذياع في إحدى الدول العربية، فهل صلاتي هذه تعتبر صلاة جماعة؟ وماذا أفعل -إذًا- وأنا أتأخر في بعض أوقات الصلاة؛ لأنه لا بد لي من الاغتسال خوفًا أن يكون عملي -الذي سبق وأن ذكرته لكم وهو في مصنع للحوم الخنازير- أخشى أن يكون في عملي هذا شيء من النجاسة، فأغتسل قبل الصلاة، أرجو توجيهي حيال ما سألت، جزاكم الله خيرًا.","title":"حكم صلاة الجمعة خلف المذياع والعمل في مصنع لحوم الخنازير","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أنّ صلاة الجمعة واجبة على المسلمين، ولكن ليس لك أن تصلي على المذياع، بل الواجب عليك أن تلتمس من المسلمين من يقيم الصلاة صلاة الجمعة، وعليك أن تجتهد في ذلك، فإذا تيسر لك جماعة من المسلمين في أي مسجد من المساجد تصلي معهم الجمعة، ولو اثنين، وتكون أنت الثالث؛ لأن الصحيح أنّ الجمعة تنعقد من ثلاثة، فإذا كانوا مستوطنين مقيمين في بلد ليسوا مسافرين بل مقيمون مستوطنون، فإنكم تصلون جميعًا جمعة، وإذا كانوا أكثر من ثلاثة فأحسن وأحسن.\nوينبغي لك وأمثالك من الإخوان الطيبين أن يسعوا في هذا الأمر، وأن يجتهدوا في إقامة صلاة الجمعة، وصلاة الجماعة في المساجد الموجودة، وأن تحرصوا على فتحها؛ لأنه بلغني أنّ هناك مساجد كثيرة مغلقة، فينبغي لك أنت وإخوانك أن تسعوا حثيثًا في فتح ما تيسر منها، وأن تقيموا صلاة الجمعة فيما تيسر منها، ولا تصل خلف مذياع، لكن إذا لم يتيسر لك أحد تصلي ظهرًا، صل أربعًا ظهرًا بعد زوال الشمس، بعد دخول الوقت، ولا تصل جمعة إلا إذا كان معك اثنان أو أكثر من الناس المستوطنين في البلد، هكذا بيّن أهل العلم.\nونسأل الله أن يجعلك مباركًا، وأن يعينك على أسباب الخير، وأن يجعلك مفتاحًا للخير. أما الغسل فهو سنة سنة مؤكدة يوم الجمعة لمن يصلي الجمعة، وذهب بعض أهل العلم إلى وجوبه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من جاء منكم الجمعة فليغتسل وقال أيضًا -عليه الصلاة والسلام-: غسل يوم الجمعة واجب على كل محتلم، وأن يستاك ويتطيب. قال جمهور أهل العلم: معنى واجب يعني: متأكد، فيسن لك الغسل للجمعة إذا كنت تصلي الجمعة. أما صلاة الأوقات فلا يشرع لها الغسل، وإذا كنت تعلم أن في ثوبك نجاسة، أو بدنك نجاسة من لحم الخنزير، أو دم الخنزير، أو من بول أو غير ذلك فاغسله، اغسل المحل فقط، وليس عليك غسل، عليك أن تغسل ما أصابه الدم أو النجاسة من الخنزير في يدك أو رجلك أو ثوبك، أما الغسل فلا يلزمك، لكن يستحب لك الغسل في الجمعة. ويجب عليك الغسل للجنابة إذا جامعت زوجتك، أو أنزلت مني بشهوة تغتسل للجنابة، نسأل الله أن يعينك على الخير، وأن يمنحنا وإياك الفقه في الدين، والثبات عليه، ونوصيك مرة أخرى بالحرص على جمع إخوانك، والتعاون معهم، وأن تصلوا جميعًا الجمعة والجماعة، وأن تجتهدوا في فتح المساجد تشجيع من حولها من المسلمين يصلوا فيها الجمعة والجماعة، كل مسجد حوله جماعة يصلوا فيه الجماعة، وإذا كانت الجمعة بعيدة عنهم صلوا جمعة أيضًا، وإذا كانوا متقاربين اجتمعوا في واحد من المساجد وصلوا جمعة، ولا يتفرقوا، بل يصلون جميعًا في مسجد واحد، إلا إذا تباعدت المساجد والمحلات تباعدًا كثيرًا، فكل حي يصلون في حيهم جمعة إذا صار بعيدًا عن الحي الآخر بما يشق معهم الذهاب إلى الحي الآخر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nسماحة الشيخ، بم توصونه تجاه عمله في هذا المصنع، مصنع للحوم الخنزير؟\nالشيخ: تقدم أن أوصيناه بأنه يجب عليه تركه، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ليس له أن يعمل في مصنع الخنزير، وليس لأحد أن يساعد صناع ما حرم الله من صناعة الخمر، أو بيع لحم الخنزير، أو غير هذا مما حرم الله، ليس للمسلم أن يشاركهم في ذلك، ولا أن يعينهم في ذلك؛ لأن الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] والنبي ﷺ لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها، والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها؛ لماذا؟ لأنهم ساعدوا على الباطل؛ لأنهم عاونوا على الشر، فلهذا لعنوا.\nفالواجب على كل مسلم وعلى كل مسلمة الحذر من الإعانة على ما حرم الله، عملًا بقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة:2] فالذي يعين على بيع الخمر، أو بيع الخنزير، أو أكل لحم الخنزير، أو شرب المسكر، أو يعين على أكل الربا، أو يكتب الربا، أو يشهد على الربا كلهم داخلون في اللعنة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12993/حكم-صلاة-الجمعة-خلف-المذياع-والعمل-في-مصنع-لحوم-الخنازير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62601.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":14740,"question":"ننتقل إلى مواضيع أخرى عبر رسائل من المستمعين الكرام، فهذه رسالة وصلت إلى البرناج من سلطنة عمان، وباعثها المستمع (س. ف. ح) أخونا يقول: استقدمت أحد العمال من الخارج للعمل لدي، وبعد مدة توفي، وتحملت نفقة تجهيزه، وترحيل جثمانه إلى بلده بما يزيد على خمسة آلاف ريال، هل علي شيء بعد ذلك تجاهه لتبرأ ذمتي؟","title":"ما يجب على صاحب العامل إذا توفي أحد عماله؟","answer":"الجواب: عليك أن تسلم لأهله الأجور التي عندك، إذا كان له أجور عندك بقايا أجور أو تركة عندك، عليك أن تسلم جميع أمواله التي عندك، من أجور، أو تركة له من نقود، أو متاع عليك أن تسلم ذلك.  أما ما أنفقته في تجهيزه فأنت أعلم بنيتك، إن كنت أنفقت ذلك تبرعًا منك، فجزاك الله خيرًا، وليس لك الرجوع بذلك، وإن كنت ما أنفقت بنية الرجوع فلك أن ترجع بما أنفقت في كفنه وحفر قبره، ونحو ذلك. أما تجهيزه إلى أهله فليس لك الرجوع، لأنه ليس واجبًا أن يرجع إلى أهله، لو دفنته مع المسلمين في بلدك، كفى، إلا إذا كان أهله طلبوا منك ذلك، ووافقوا على أن تأخذ قيمة تجهيز السفر من ماله فلا بأس، وإلا فليس عليك أن تجهزه إلى بلده، بل الواجب أن يدفن مع المسلمين في عمان، كما لو مات في مكة أو المدينة أو غير ذلك، يدفن مع المسلمين، ولا يرسل إلى بلاده، لكن لو طلب أهله إرساله إلى بلاده، والتزموا بالنفقة، أو سمحوا بأخذ النفقة من التركة فلا بأس، مع أن ترك ذلك أفضل، كونه يدفن مع المسلمين، ولا يسفر أولى من التكلف، هذا هو الأولى، إنما يتكلف في ذلك إذا كان في بلاد الكفار، في بلاد لا يدفن فيها المسلم هذا لا بأس في نقله إلى بلد مسلم، أو إلى أهله، أو سمح أهله بنقله إليهم لمصلحة رأوها يكون على حسابهم، على حساب من سمح بذلك من طلب نقله، والتزم بقيمة التذاكر، أما أنت فلا يلزمك ذلك لكن إذا تبرعت بذلك فليس لك الرجوع. المقدم: بارك الله فيكم.\nإذا كان ذلك العامل غير مسلم؟\nالشيخ: إذا كان العامل غير مسلم لا يكفن، ولا يصلى عليه، ولا يجهز إلى بلاد قومه يدفن مع الكفار إن كان في بلدك فيها كفار، أو يحفر له في محل بعيد عن المسلمين، ويدفن في محل بعيد في الصحراء، ويواسى قبره وانتهى الأمر، ولا يصلى عليه ولا يغسل ولا يكفن، بل يدفن فيما تيسر من الثياب الساترة. المقدم: يستر في ثياب، ويدفن بعيدًا عن مقابر المسلمين؟ الشيخ: هكذا هكذا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13258/ما-يجب-على-صاحب-العامل-اذا-توفي-احد-عماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63008.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":14968,"question":"من المستمعة السائلة أم رزاق تقول في رسالتها: إنني ربة بيت، وشغلي أخيط ملابس نسائية، وملابس أطفال، والأجرة التي أقتضيها أصرفها على البيت والأولاد؛ لأن زوجي حالته متواضعة، هل علي زكاة وإني أخيط منذ عشر سنوات، لكن لم أجمع مال أصرفه أولًا بأول؟أرشدوني أثابكم الله، وجزاكم الله خيرًا.","title":"حكم العمل في الخياطة وزكاة أجرتها","answer":"الجواب: أنت مأجورة، جزاك الله خيرًا للمساعدة لزوجك، والقيام على أولادك وهذا العمل طيب؛ لقول النبي ﷺ لما سئل: أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور، وهذا من عمل اليد، الخياطة من عمل اليد، وفي الحديث الصحيح يقول -عليه الصلاة والسلام-: ما أكل أحد طعامًا خيرًا من أن يأكل من عمل يده، وإن نبي الله داود -عليه الصلاة والسلام- كان يأكل من عمل يده هذا العمل طيب، وأنت مأجورة في عملك، وعليك أن تنصحي في الخياطة، وعليك أن تتقي الله في الخياطة، وتنصحي، وأنت مأجورة بذلك والكسب طيب، ولا حرج في ذلك، وأنت في إحسانك إلى زوجك وإلى أولادك أنت مأجورة في ذلك. فالخلاصة: أن الخياطة والنجارة والحدادة والكتابة كلها مكاسب طيبة. هكذا التجارة إذا نصح المؤمن في ذلك، ولم يخن، ولم يكذب، تحرى النصيحة وأداء الأمانة، وعدم الكذب، وعدم الغش فهو مأجور والكسب طيب، أما إذا دخلها الخيانة والكذب، هذا لا يجوز نسأل الله العافية، والله يقول -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27] ويقول النبي ﷺ في البيعين، البائع والمشتري: فإن صدقا وبينا، بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما. فالمهم في أعمال اليد النصح، والجد وعدم الغش، وعدم الخيانة، وبذلك تكون المكاسب طيبة في البيع والشراء، والخياطة، والنجارة، والحدادة، وغير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13470/حكم-العمل-في-الخياطة-وزكاة-اجرتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49208.mp3","categories":["قضايا المرأة","الإجارة"]},{"id":15090,"question":"سؤاله الأخير طويل جدًا، يقول فيه: إنه عرض علي تاجر العمل معه في محل، بقالة، واتفق معي على أن يعمل هو صباحًا، وأنا أعمل مساءً، وحدد لي المصروف اليومي على أساس أن يكون هناك جرد كل ثلاثة شهور، فإذا كان العمل رابحًا، وصار لي باقي؛ أخذته، وإذا كان عكس ذلك، خفض لي المصروف، أو أنهى العقد معي، يقول في ذلك -الرسالة طويلة، نستطيع أن نلخصها-:بأن صاحب المحل عرض على هذا العامل أن يفتح معه معرض، ويكون بالتساوي بينهما، وهو يريد أن يأخذ من المعرض خسارته في هذه النسبة، يقول هذا الذي بعث لنا بالرسالة: إنني أخفي عليه بعض الحاجات من النقود؛ لأن صديقًا لي قال: إن صاحب المتجر سيلعب عليك، ويأخذ خسارته في الشراكة الأولى، فأخفيت هذا المبلغ، وقلت في نفسي: أريد أن أعرف إذا كان يريد أن يلعب علي؛ أخذت نقودي، وإذا كان صادقًا؛ رجعت نقودي هذه إليه، وفعلًا أصبح يريد أن يلعب علي؛ ولذلك لم أرجع هذه النقود، التي أخذتها خفية، هل فيها شيء أم لا؟","title":"حكم إخفاء العامل بعض النقود لتلاعب رب العمل بحقوقه","answer":"الجواب: السؤال فيه إجمال، وفيه بعض الغموض، ولكن نجيبه على التفصيل:  إذا كان هذا السائل اتفق مع التاجر على راتبٍ معلوم شهريًا، في ثلاثة أشهر، أو أقل، أو أكثر، ثم بعد مضي المدة، ينظرون في البقالة، ويتأملون البقالة، فإن كانت البقالة رابحة، جدد معه العقد، وإلا فلا، هذا معناه صحيح. إذا اتفق معه على راتب معلوم، شهرين، أو ثلاثة، أو أربعة، أو خمسة، ثم بعد ذلك ينظرون في البقالة، ويصفون حسابها، فإن رأوا أنها رابحة، والعمل ناجح؛ جدد له العقد مرةً أخرى، بأقل أو بأكثر، وإن لم يروا ذلك؛ أمكنه فسخ العقد، فهذا لا بأس به؛ لأنه ليس فيه غرر. أما إن كان مراده غير ذلك، فليوضح مراده، نعم.","link":"https://binbaz.org.sa/fatwas/13587/حكم-اخفاء-العامل-بعض-النقود-لتلاعب-رب-العمل-بحقوقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65505.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":15428,"question":"هذه السائلة من محافظة شمال سيناء السائل (ج. م. ع) يقول: لدي هذا السؤال، يقول: أنا موظف، ولكن لا أذهب إلى عملي في كل يوم؛ لأن عملي لا يتطلب ذلك، بل أذهب في الأسبوع ثلاثة أيام، وباقي الأسبوع أجلس في البيت، ولكن عندما أذهب باقي الأسبوع لا أجد عملًا أقوم بعمله، بل نجلس نتجاذب الحديث بيننا دون عمل، فما حكم الإسلام في نظركم في المرتب الذي أتقاضاه، هل هو حرام أم حلال؟","title":"حكم تقاضي مرتب في وظيفة قليلة أعمالها","answer":"الجواب: الواجب عليك الحضور في محل العمل؛ لأنه قد يأتي عمل ويطرأ، فالواجب عليك الحضور، والاستعداد للعمل، وإن لم يأت عمل، ولا تجلس في بيتك، والراتب لا حرج فيه لأنك متأول، تقول: ما عندك عمل فأنت متأول، ولكن يجب عليك أن تذهب إلى محل العمل، وتقيم فيه وقت العمل، قد يطرأ شيء، قد تسأل عن شيء، فلا يجوز التساهل في هذا الأمر، فأنت مستعد، والحمد لله، تكون مستعدًا في محل العمل، ويكفي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13944/حكم-تقاضي-مرتب-في-وظيفة-قليلة-اعمالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50009.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":15569,"question":"هذا السائل (م. ع. أ) يقول يا سماحة الشيخ: بأنه شاب كان يعمل بشركة من الشركات، ولكن يقول: فوجئت من أن الشركة قد خصمت علي أشياء بدون وجه حق، هذا من ناحية، ومن الناحية الأخرى قدمت أعمالًا أستحق عليها المكافأة، ولم يعطوني إياها، فاضطررت إلى أن أعمل ما يلي:عندما كنت أشتري أشياء للشركة كنت أحصل على خصم كبير من أصحاب المحلات، ولكن هذا بيني وبين أصحاب المحلات، وكنت آخذ الخصم في جيبي مثلًا الفاتورة بمائة جنيه أخذ خمسة وعشرين جنيهًا، والفاتورة تكتب بمائة، مع العلم أن الأسعار بالفاتورة مثل المحلات الخارجية، أي: أن قيمة الفاتورة لا تزيد عن الطبيعي، ولكن الذي يحدث هو زيادة الخصم لكثرة الشراء، ولا يكتب الخصم بالفاتورة.","title":"خصمت عليه الشركة فأخذ ما تعطى من خصم من المحلات","answer":"الجواب: الواجب عليك أن تحاسبهم، وأن تخاصمهم، حتى يكون الأمر بينًا، أما الخصم هذا فقد يزيد، وقد ينقص، وقد تكون متساهلًا فيما تدعي أنه حق لك، فالواجب عليك أن تكون المسألة بينك وبينهم من جهة الصلح، بينك وبينهم بواسطة من يتيسر من المصلحين، أو بواسطة المحكمة، وأن لا تفعل ما ذكرت؛ لأنك قد تزيد على ما أخذ منك، وقد تتساهل في الأمور، وقد تظن أنك مظلوم وأنت غير مظلوم، فالواجب أنك تحاسبهم بالمناقشة بينك وبينهم، أو بواسطة المصلحين والأخيار، أو بواسطة المحكمة إن دعت الحاجة للخصومة، هذا هو الواجب عليك حتى لا تأخذ إلا حقك. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14108/خصمت-عليه-الشركة-فاخذ-ما-تعطى-من-خصم-من-المحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57007.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":15931,"question":"هذه أختكم في الله (م. أ) من الجنوب تقول: سماحة الشيخ، معلمة للقرآن الكريم تتحرج كثيرًا من أخذ الراتب الشهري على ذلك. علمًا بأن الطالبات يدفعن مبلغًا من المال كل شهر؛ وذلك لتغطية رواتب المعلمات، ومستلزمات المدرسة، فما الحكم في ذلك؟ مأجورين.","title":"هل في أخذ الأجرة على تعليم القرآن حرج؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فليس هناك حرج في أخذ المعلمة والمعلم أجرًا على التعليم؛ لقوله ﷺ في الحديث الصحيح: إن أحق ما أخذتم عليه أجرًا كتاب الله خرجه البخاري في الصحيح؛ ولأن جماعة من الصحابة -رضي الله عنهم وأرضاهم- مروا على جماعة من البادية قد لدغ سيدهم فلم يقروهم، فطلبوا منهم أن يرقوا سيدهم، فقال لهم الصحابة: لم تضيفونا، ولا نقرأ عليه إلا بجعل، فاتفقوا معهم على جعل من الغنم، قطيع من الغنم، فقرؤوا عليه، فشفاه الله، فأعطاهم القطيع من الغنم، فقالوا: لا نفعل شيئًا حتى نستأذن الرسول ﷺ، فلما قدموا المدينة أخبروا الرسول ﷺ فقال: أصبتم، واضربوا لي معكم بسهم فدل على أنه لا حرج في أخذ الأجرة على التعليم وعلى القراءة على المريض كل هذا لا بأس به، والحمد لله، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14528/هل-في-اخذ-الاجرة-على-تعليم-القران-حرج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57801.mp3","categories":["الإجارة","القرآن وعلومه"]},{"id":15988,"question":"السائل فواز له مجموعة من الأسئلة يقول في بداية أسئلته سماحة الشيخ: ما حكم أخذ الأجرة على السمسرة؟","title":"حكم أخذ الأجرة على الدلالة","answer":"الجواب: لا حرج، أخذ الأجرة كونه يكون دلالًا يبيع البيوت، يبيع الأراضي، يبيع الإبل، يبيع الغنم، يبيع الرقيق ويأخذ أجرة، لا بأس، أجرته، هذا عمله.","link":"https://binbaz.org.sa/fatwas/14592/حكم-اخذ-الاجرة-على-الدلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57816.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16246,"question":"من المستمع إسماعيل محمد موسى مقيم في مكة المكرمة رسالة يقول فيها: لنا في السودان أدوات تؤجر للمناسبات، كمكبرات الصوت، والكراسي، والصيوانات، ومفارش، وكوش لجلوس العروسين يوم الزفاف، علمًا بأن هذه الأشياء أحيانًا تؤجر للمآتم، والندوات الدينية، والثقافية، فهل هذا يجوز، أم لا؟ جزاكم الله خيرًا.","title":"حكم تأجير بعض الأدوات للمناسبات والمآتم","answer":"الجواب: تأجيرها في المناسبات المباحة، والمشروعة لا بأس بذلك، إذا أجرها صاحبها لوليمة العرس التي ليس فيها منكر، أو لمناسبات أخرى، ليس فيها منكر؛ مباحة لا بأس، أما تأجيرها على قوم يفعلون فيها المنكر، من إنشاد المآتم التي تعتبر بدعة، كإيجاد الوليمة من أهل الميت إذا مات الميت، هذا بدعة، ومن عمل الجاهلية، كونهم يقيمون وليمة عند موت ميتهم، هذا من البدع، ومن أمر الجاهلية، يقول جرير بن عبدالله البجلي : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة\". فالمقصود: أن كون أهل الميت يعدون طعامًا للناس مأتمًا، وحزنًا، فهذا من عمل الجاهلية، لا يؤجر عليهم لا الكراسي، ولا غيرها. وهكذا إذا كان يقام في الاحتفال أمور منكرة من الملاهي، والعود، والسينما، وأشباه ذلك مما يعتبر محرمًا؛ فلا يجوز ذلك. فالخلاصة: أنها إن أجرت على من يستعملها في أمر مشروع، أو مباح؛ فلا بأس، وإن أجرت على من يستعمل فيها المنكر، أو يستعملها في بدعة؛ فلا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14932/حكم-تاجير-بعض-الادوات-للمناسبات-والماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80705.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16593,"question":"المستمع سريح القرني من رأس تنورة بعث يسأل ويقول: لدينا مزرعة، وعليها عمال، حيث نعطيهم رواتب شهرية حسب اتفاقية الاستقدام من دولتهم، ولكن بعض الأحيان يطلبوا منا إعطاءهم المزرعة بالنصيفة، بدون راتب، على أن نقوم نحن أصحاب المزرعة بإعداد متطلبات المزرعة من المضخات، والوقود، وكذلك آلات الحرث، ومقابل أن يقوم العمال بزراعة المزرعة، وبيعها في الأسواق في سياراتنا، وعند انتهاء الثمرة نقتسم بالنصف فيما بيننا فما الحكم في ذلك؟ وهل علينا شيء في هذا؟ وهل هذا يدخل في كراء الأرض المنهي عنه؟ لأنني قرأت أحاديث تدل على النهي عن كراء الأرض، مثاله: عن جابر بن عبدالله -رضي الله عنهما- أن النبي ﷺ قال: من كانت له أرض؛ فليزرعها، أو ليزرعها أخاه، ولا يكرها مختصر صحيح مسلم، جزاكم الله خيرًا.","title":"حكم تأجير الأرض على شيء معلوم","answer":"الجواب: عملكم هذا طيب، ولا بأس، هذه مزارعة، فإذا أعطيتم العمال النصف، أو الثلث، أو الربع على قيامهم على المزرعة، وسقيهم لها، وتعبهم فيها، وأنتم تعدون لهم كل شيء؛ فلا بأس بذلك، هذه مزارعة جائزة، ولا حرج فيها، ولا بأس بتأجير الأرض على الناس بأجر معلوم، كان هذا الذي ذكرت الحديث كان هذا في أول الإسلام، ثم نسخ، كان النبي ﷺ نهى عن تأجير الأرض، ثم رخص في ذلك عليه الصلاة والسلام.  فإذا زارع عليها بالنصف، أو بالثلث؛ فلا بأس، أو أجرها بشيء معلوم، والمستأجر يزرعها، أو يغرس فيها فلا بأس؛ لأن هذه أمور معلومة، أما الذي بقي النهي عنه، ولم يزل ينهى عنه الرسول ﷺ فهو تأجيرها بشيء مجهول، كأن يزارع على شيء مجهول من الزرع، بأن يعطيه ما أنبتت الجهة الفلانية، أو ما نبت على السواقي، فهذا خطر، قد يكون رديء، وقد يكون طيبًا، هذا منهي عنه، وأما الشيء المضمون بدراهم معلومة، أو آصع معلومة، أو بجزء مشاع، كالنصف، أو بالثلث هذا لا بأس به. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15324/حكم-تاجير-الارض-على-شيء-معلوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81707.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16645,"question":"ما رأي سماحتكم فيمن يتقاضى أجرًا عما يقوم به من الدعوة إلى الله، وتحفيظ القرآن الكريم؟","title":"حكم أخذ الأجرة على تعليم القرآن والدعوة إلى الله","answer":"الجواب: لا حرج في ذلك، المعلم يعطى على تحفيظ القرآن، وتعليم القرآن، والدعوة إلى الله  لأن هذه الأمور تحتاج إلى أوقات، وكلفة ومشقة، فإذا أعطي من بيت المال، ومن أوقاف المسلمين، أو من بعض المحسنين ما يعينه على التعليم، والتحفيظ، والدعوة إلى الله، أو التدريس كله طيب، لا حرج فيه، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15378/حكم-اخذ-الاجرة-على-تعليم-القران-والدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71708.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16830,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد صبري، أخونا له قضية يقول فيها: إنني أعمل مع أحد التجار، وهذا التاجر يعطيني المصروف يوميًا للمواصلات، وللأكل والشرب، لكنني لا أصرف ذلك المبلغ كله في الأكل والشرب، وإنما أصرف بعضه، والباقي أوفر منه، لكني أوفر على الوقت بحيث أستهلك وقتًا أطول.. أو فيما لو صرفت المبلغ كاملًا، وجهوني جزاكم الله خيرًا، هل ما أنا عليه صحيح، أو لا بد من اتباع ما طلب ذلكم التاجر؟ جزاكم الله خيرًا.","title":"حكم توفير العامل المصاريف بما بؤثر على العمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كنت متفقًا معه على مصرف معين، فأنت بالخيار تأكله كله، أو بعضه، لا حرج عليك، فقد طابت نفسه بذلك، وأنت أبصر بنفسك، تصرف الجميع، أو بعضه، نعم. المقدم: جزاكم الله خيرًا، يقول: إنه يؤثر على الوقت سماحة الشيخ بحيث يستهلك وقتًا أطول إذا لم يصرف المصروف كاملًا، ولاسيما في موضوع المواصلات كما يقول. الشيخ: إذا كان التقصير يؤثر على العمل؛ فلا يجوز لك، لا بد أن يكون العمل وافرًا كاملًا، فإذا كان عدم صرفك المصروف على وجه أكمل يؤثر على العمل، أو ينقص العمل؛ فلا يجوز لك، لا بد أن يكون العمل كاملًا كما شرط عليك كما اتفقتما، وعليك أن تصرف ما أعطيته إذا كان يعينك على العمل، ولا يحصل به تقصير، الحاصل أنه لا بد من إكمال العمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15586/حكم-توفير-العامل-المصاريف-بما-بوثر-على-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71901.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":16899,"question":"هل يجوز تأجير مطعم بكامل معداته، وأدواته، وعماله على شخص مستأجر، على أن يدفع المستأجر مبلغًا معينًا ثابتًا شهريًا للمؤجر، سواء ربح المطعم، أو خسر، مع العلم أن المستأجر يأخذ راتبًا شهريًا من المؤجر، وأيضًا المتبقي الصافي بعد خصم المبلغ المخصص للمؤجر، سواء كان قليلًا، أو كثيرًا؟","title":"حكم أخذ المستأجر أجرة من المؤجر","answer":"الجواب: .... على تأجير المطعم الأدوات التي فيه تأجيرها على زيد، أو عمرو لا بأس إذا كان بأجر معلوم لمدة معلومة، وهو يستعمل هذه الأشياء التي في المطعم من كراسي، ومن فرش، ومن أدوات، ومن أواني يستعملها في إطعام الناس، وفي صنع الولائم لهم، لا بأس بذلك، لكن كونه أجيرًا لصاحب المطعم، أي وجه لهذا مادام المطعم قد استأجره؟ كيف يكون أجيرًا له هو وهو استأجر المطعم؟ كيف يصير هذا وكونه مستأجرًا للمطعم يتصرف فيه..... يطعم الناس، ويأخذ الأجرة من الناس، فعلى أي وجه يأخذ أجرة هو وهو صاحب المطعم، وهو الذي استأجر المطعم، وصار يطعم الناس، ويأخذ منهم قيمة الطعام، والشراب؟ هذا غريب، محل نظر، نرى أن صاحب المطعم يتصل بي أحسن؛ حتى أشوف موضوعه، يتصل بي مشافهة حتى يدرس الموضوع معه؛ لأن السؤال فيه غرابة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15657/حكم-اخذ-المستاجر-اجرة-من-الموجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71906.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":17090,"question":"من المستمع (ك. م. ع) من السودان رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: أنا أعمل مع أحد التجار، وهذا التاجر يدفع رشاوى حتى يسير عمله، علمًا بأنني أدير له أعماله الحسابية فقط، وأتقاضى على ذلك أجرًا، فهل يعتبر هذا المبلغ الذي آخذه حرام بالنسبة لي؟ أفيدونا أفادكم الله.","title":"حكم راتب من يعمل عند من يتعامل بالرشوة","answer":"الجواب: نرجو ألا يكون عليك شيء، والإثم عليه لما يدفع من الرشوة، الإثم عليه، وأنت -إن شاء الله- إذا كنت لا تعمل إلا ما أباح الله لا شيء عليك، لكن تنصحه، تنصحه وتحث إخوانك على نصيحته؛ لأن الرشوة حرام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15943/حكم-راتب-من-يعمل-عند-من-يتعامل-بالرشوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83111.mp3","categories":["الإجارة","أحكام الموظفين"]},{"id":17441,"question":"ننتقل إلى قضية أخرى عبر رسالة وصلت إلينا من القصيم، وباعثها مستمع رمز إلى اسمه بالحروف (ر. غ. ش) يقول: تعينت في وظيفة، وولدي في وظيفة أخرى، والراتب ما يقرب من ألفي ريال، ثم حصلت على وظيفة تبعد عن القرية التي أنا فيها، والتي أيضًا الوظيفة فيها مسافة أربعين كيلو مترًا، فاستقدمت إنسانًا براتب سبعمائة ريال ليقوم بوظيفتي، ووظيفة ابني، لكن ذلك الشخص غير راضٍ، فما حكم ما فعلت؟ جزاكم الله خيرًا.","title":"حكم النيابة في العمل مقابل جزء من الراتب","answer":"الجواب: إذا لم يكن راضيًا؛ فليس لك إجباره أنت، ولا غيرك، وإذا رضي؛ فلابد من استئذان مرجعك في الوظيفة: هل يرضى بهذا النائب عنك، أم لا يرضى؟ فلا بد من رضا المرجع في الوظيفة الأولى، ولابد من رضا النائب عنك الذي استأجرته؛ ليقوم بعملك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16298/حكم-النيابة-في-العمل-مقابل-جزء-من-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83602.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":17577,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين من القصيم رمز إلى اسمه بالحروف ( س. ف ) يقول: صاحب مزرعة عنده عامل لغرض المزرعة فقط، وصاحب المزرعة يشتغل فراش في مسجد، وبعض الأوقات يأخذ العامل إلى المسجد لكي يقوم العامل بنظافة المسجد، والمرتب لصاحب المزرعة، هل يحق له ذلك أو لا؟","title":"حكم تكليف العامل بأعمال أخرى بدون أجر","answer":"الجواب: إذا سمح العامل فلا بأس، إذا سمح أن يذهب إلى المسجد ويقوم بخدمة المسجد فلا بأس، أما إذا لم يسمح فليس له إلزامه؛ لأن العمل اللي عنده في المزرعة، استأجره ليعمل في المزرعة، أما إذا سمح العامل أنه يخدم المسجد فهذا قربة وطاعة لا بأس الحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16503/حكم-تكليف-العامل-باعمال-اخرى-بدون-اجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83904.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":18409,"question":"يسأل هذا السائل يا فضيلة الشيخ! ويقول: ما حكم أخذ الأجرة على تعليم القرآن والعلم الشرعي في المساجد والمدارس؟","title":"حكم أخذ الأجرة على تعليم القرآن والعلم الشرعي","answer":"الجواب: لا حرج في ذلك؛ لقوله ﷺ: إن أحق ما أخذتم عليه أجرًا كتاب الله فلا بأس أن يأخذ من المتعلم أجرة يعلمه القرآن أو يعلمه الأحاديث. نعم.","link":"https://binbaz.org.sa/fatwas/17483/حكم-اخذ-الاجرة-على-تعليم-القران-والعلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91335.mp3","categories":["الإجارة"]},{"id":18491,"question":"أخونا يسأل ويقول: أرجو أن توجهوا أصحاب المؤسسات كي ما يكثروا من العمال المسلمين؛ لأني ألاحظ أن معظم عمال المؤسسات من غير المسلمين، بل ومن غير الكتابيين أيضًا فهم يصلون إلى نسبة تسعين في المائة؟","title":"الحث على استقدام العمال المسلمين","answer":"الجواب: قد سبق منا غير مرة التنبيه على هذا، وأن الواجب على المؤسسات والشركات وعلى غيرهم ممن يستورد العمال ألا يستورد إلا المسلمين في هذه الجزيرة بوجه أخص؛ لأن هذه الجزيرة مهد الإسلام ومطلع شمس الرسالة، ومرجع المسلمين، وفيها الحرمان الشريفان، ولهذا أمر النبي ﷺ بإخراج المشركين منها وأوصى بذلك عند وفاته أن يخرجوا من هذه الجزيرة سواء كانوا يهودًا أو نصارى أو وثنيين أو شيوعيين .. جميع أنواع الكفرة يجب إخراجهم من هذه الجزيرة وأن لا يبقى فيها إلا مسلم، ونهى أن يجتمع بها دينان، فلا يجوز بقاء دين آخر غير الإسلام في هذه الجزيرة، لا من العمال ولا من السكان بل يجب إخراجهم إلا من وردها لحاجة عارضة كالبريد والتاجر الذي يبيع حاجته وينصرف ونحو ذلك بصفة مؤقتة وأيام معدودة. فعلى المؤسسات والشركات والأفراد وعلى الدولة وفقها الله أن تعنى بهذا الأمر وأن تأخذ على أيدي الناس وأن تمنع من استيراد الكفار إلا عند الضرورة القصوى في مصلحة المسلمين فيما يتعلق بالدولة إذا احتيج إلى بعض الكفرة لمصلحة المسلمين ولم يتيسر من يقوم بعمله غيره. أما عموم الناس فالواجب منعهم من استيراد الكفرة وألا يستوردوا إلا مسلمين في عمل البناء وفي غير ذلك من الأعمال، هذا هو الواجب على المسلمين جميعًا، وأن يعملوا بما أوصى به نبيهم عليه الصلاة والسلام من إخراج الكفار من هذه الجزيرة وعدم استيرادهم لها، لما في اختلاطهم بالمسلمين من الأضرار العظيمة والأخطار الكثيرة. نسأل الله أن يوفق المسلمين لما يرضيه، وأن يوفق الدولة لتنفيذ أوامر الله ورسوله في كل شيء، وأن يعينها على ذلك إنه خير مسئول. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17596/الحث-على-استقدام-العمال-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86707.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":18873,"question":"أخونا يسأل ويقول: أرجو أن توجهوا أصحاب المؤسسات؛ كي يكثروا من العمال المسلمين؛ لأني ألاحظ أن معظم عمال المؤسسات من غير المسلمين، بل ومن غير الكتابيين أيضًا، فهم يصلون إلى نسبة تسعين بالمائة.","title":"حكم استقدام الكفرة إلى جزيرة العرب للعمل وغيره","answer":"الجواب: قد سبق منا غير مرة التنبيه على هذا، وأن الواجب على المؤسسات والشركات -وعلى غيرهم ممن يستورد العمال- أن لا يستورد إلا المسلمين، في هذه الجزيرة بوجه أخص؛ لأن هذه الجزيرة مهد الإسلام، ومطلع شمس الرسالة، ومرجع المسلمين، وفيها الحرمان الشريفان؛ ولهذا أمر النبي ﷺ بإخراج المشركين منها، وأوصى بذلك عند وفاته أن يخرجوا من هذه الجزيرة، سواء كانوا يهودًا أو نصارى أو وثنيين أو شيوعيين. جميع أنواع الكفرة، يجب إخراجهم من هذه الجزيرة، وألا يبقى فيها إلا مسلم، ونهى أن يجتمع فيها دينان، فلا يجوز بقاء دين آخر غير الإسلام في هذه الجزيرة، لا من العمال، ولا من السكان، بل يجب إخراجهم، إلا من وردها لحاجة عارضة: كالبريد، والتاجر الذي يبيع حاجته وينصرف، ونحو ذلك، بصفة مؤقتة وأيام معدودة. فعلى المؤسسات والشركات والأفراد، وعلى الدولة -وفقها الله- أن تعنى بهذا الأمر، وأن تأخذ على أيدي الناس، وأن تمنع من استيراد الكفار إلا عند الضرورة القصوى في مصلحة المسلمين، فيما يتعلق بالدولة، إذا احتيج إلى بعض الكفرة لمصلحة للمسلمين، ومن لم يتيسر من يقوم بعمله غيره. أما عموم الناس فالواجب منعهم من استيراد الكفرة، وأن لا يستوردوا إلا مسلمين: في عمل البناء، وفي غير ذلك من الأعمال، هذا هو الواجب على المسلمين جميعًا، وأن يعملوا بما أوصى به نبيهم -عليه الصلاة والسلام- من إخراج الكفار من هذه الجزيرة، وعدم استيرادهم لها، لما في اختلاطهم بالمسلمين من الأضرار العظيمة، والأخطار الكبيرة. نسأل الله أن يوفق المسلمين لما يرضيه، وأن يوفق الدولة لتنفيذ أوامر الله ورسوله في كل شيء، وأن يعينها على ذلك إنه خير مسؤول. المقدم: جزاكم الله خيرًا، معي في المؤسسة عمال غير المسلمين، ولا حتى من أهل الكتاب، كلما علمتهم شيئًا استعملوه ضدي، فهل أمتنع عن تعليمهم أي شيء، ويكون هذا حلال أم حرام؟ الشيخ: الواجب عليك ألا تستورد كفارًا، وأن تبعدهم إلى بلادهم، وأن تنهي عقودهم، وأن لا تخبرهم بشيء يضرك، وإنما تنصحهم، تدعوهم إلى الإسلام، وتعلمهم ما ينفعهم، أما أن تعلمهم شيء يضرك، فلا تعلمهم شيء يضرك، بل أبعدهم وأنه عقودهم، واتق الله، واتبع رسوله -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/18034/حكم-استقدام-الكفرة-الى-جزيرة-العرب-للعمل-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88007.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":19015,"question":"رسالة وصلت إلى البرنامج من المستمع عبد العزيز عبد الجليل من مصر محافظة الفيوم يسأل ويقول: ما حكم أخذ الأجرة على تدريس القرآن الكريم في مدارس تحفيظ القرآن الكريم؟","title":"حكم أخذ الأجرة على تدريس القرآن الكريم","answer":"الجواب: لا حرج في ذلك، الصحيح أنه لا بأس بذلك؛ لأن في أخذ الأجرة إعانة له على الاستمرار في التعليم والصبر عليه؛ ولأن كثيرًا من الناس قد لا يستطيع أن يعلم بدون شيء؛ لأنه ليس له دخل يقوم بحاله، حتى يتفرغ للتعليم، فإذا أعطي أجرة على ذلك تفرغ للتعليم ونفع الناس. وقد روى البخاري في صحيحه عن ابن عباس رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام أنه قال: إن أحق ما أخذتم عليه أجرًا كتاب الله وهذا يشمل التعليم، التعليم هو أهم ما يكون فيما يتعلق بالقرآن تعليم الناس، وتوجيههم، إرشادهم، هذا يحفظ وهذا يعلم، هذا من أهم المهمات ومن أفضل القربات، فإذا أخذ عليه أجرة تعينه على هذا الأمر العظيم فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18184/حكم-اخذ-الاجرة-على-تدريس-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92703.mp3","categories":["الإجارة","القرآن وعلومه"]},{"id":19286,"question":"تسأل أختنا وتقول: هل يجوز عدم دفع أجرة الخياط كاملة؛ لأنه مرتفع الثمن؟","title":"حكم عدم دفع أجرة الخياط كاملة بسبب الأجرة المرتفعة","answer":"الجواب: يقول النبي ﷺ: المسلمون على شروطهم والله يقول فوق ذلك: يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ [المائدة:1]، فإذا تعاقدت المرأة أو الرجل مع الخياط على شيء معلوم، وجب عليهم أداؤه مرتفعًا أو غير مرتفع، المسلمون على شروطهم، ويقول عمر : مقاطع الحقوق عند الشروط، فإذا اتفقا على أنه يخيط هذا الثوب بعشرة أريل.. بعشرين.. بثلاثين، واتفقا على هذا، وسلموا له الثوب، وجب عليهم أن يؤدوا له الأجرة . نعم . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18489/حكم-عدم-دفع-اجرة-الخياط-كاملة-بسبب-الاجرة-المرتفعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89306.mp3","categories":["الأذان والإقامة","الإجارة"]}]
